// Module-scope mutable data source.
// In standalone mode, defaults to the stubs above.
// In integration mode, the SalesOrders component synchronously assigns shell-provided arrays to these
// at the top of its render, BEFORE any of the LOTS/PO_REFS readers run. Because React renders synchronously,
// every helper called downstream (computeLineAvailability, SourcePickerModal, save guards) sees the updated values.
//
// We're using `let` here intentionally — these are NOT React state, they're just references to whatever
// state the parent owns. Treating them as `const` would force us to plumb props through ~14 call sites in
// 4 different functions. The render-time assignment pattern is safe given React's synchronous render model.
let LOTS: any[] = [];      // Batch 0 (G1): no stub fallback — live props only
let PO_REFS: any[] = [];   // Batch 0 (G1): no stub fallback — live props only
// v6.41.0 (A5): raw lots (with .movements) + shipments, for the unshipped-
// remainder reservation rule. The adapted LOTS above lose .movements, so we
// keep the raw arrays here for shippedKgByLine.
let RAW_LOTS: any[] = [];
let SHIPMENTS_REF: any[] = [];
function reserveCtx() { return RAW_LOTS.length ? { lots: RAW_LOTS, shipments: SHIPMENTS_REF } : undefined; }

// Convert the lots into the Inventory→SalesOrders interface shape.
// Inventory stores: { number, product, quality, size, origin, warehouse, physicalKg, ... }
// SalesOrders expects: { number, product, quality, size, origin, warehouse, availableKg, packaging }
// We map physicalKg → availableKg so the source picker can still display a baseline figure.
// (The TRUE live availability is computed downstream by lotReservations with the SO list.)
function _adaptLotsFromInventory(invLots) {
  return (invLots || []).map(l => ({
    number: l.number,
    product: l.product,
    variety: l.variety || "",
    cnCode: l.cnCode || "",
    poRef: l.poRef || "",
    status: l.status || "",
    arrivalDate: l.arrivalDate || "",
    quality: l.quality,
    size: l.size,
    origin: l.origin,
    warehouse: l.warehouse || "—",
    availableKg: l.physicalKg ?? l.receivedKg ?? 0,
    physicalKg: l.physicalKg ?? 0,
    receivedKg: l.receivedKg ?? 0,
    packaging: l.packaging,
  }));
}

// Convert POs from the PO module shape into the SalesOrders source-picker shape.
// PO has supplier:{name,country,...}, expectedDeliveryDate; SO wants flat supplierName, expectedDelivery.
// PO items lack an 'available' field — SO needs it for the picker. We set it to qty (full line),
// and let poLineReservations subtract live SO commitments downstream.
function _adaptPOsFromModule(pos) {
  return (pos || []).map(po => ({
    number: po.number,
    status: po.status,
    supplierName: po.supplier?.name || po.supplierName || "—",
    country: po.supplier?.country || po.country || "—",
    expectedDelivery: po.expectedDeliveryDate || po.expectedDelivery || "—",
    items: (po.items || []).map(it => ({
      ...it,
      available: it.available ?? (parseFloat(it.qty) || 0),
    })),
  }));
}

