// Resolve the supplier name for a PO-sourced line (from the SO's PO references)
function supplierNameForPO(poRef: any): string {
  const po: any = (PO_REFS || []).find((p: any) => p.number === poRef);
  return po?.supplierName || po?.supplier?.name || "";
}


// ─── LIFECYCLE BAR ────────────────────────────────────────────────────────
function LifecycleBar({ status }: any) {
  const stages = ["Draft", "Confirmed", "Reserved", "Loading", "Shipped", "Delivered", "Invoiced", "Closed"];
  const currentOrder = SO_STATUSES[status]?.order ?? 0;
  const isCancelled = status === "Cancelled";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
      {stages.map((s, i) => {
        const stageOrder = SO_STATUSES[s].order;
        const past = !isCancelled && stageOrder < currentOrder;
        const current = !isCancelled && stageOrder === currentOrder;
        return (
          <React.Fragment key={s}>
            <div style={{
              padding: "4px 9px", borderRadius: 14, fontSize: 10.5, fontWeight: 600,
              background: current ? SO_STATUSES[s].bg : (past ? "#F3F4F6" : "#FAFAFA"),
              color: current ? SO_STATUSES[s].color : (past ? "#374151" : "#CCC"),
              border: current ? `1px solid ${SO_STATUSES[s].color}` : "1px solid transparent",
              whiteSpace: "nowrap",
            }}>{past && "✓ "}{s}</div>
            {i < stages.length - 1 && <div style={{ width: 8, height: 1, background: past ? "#9CA3AF" : "#E5E7EB" }} />}
          </React.Fragment>
        );
      })}
      {isCancelled && <span style={{ marginLeft: 8, padding: "4px 9px", borderRadius: 14, fontSize: 10.5, fontWeight: 600, background: "#FEE2E2", color: "#DC2626" }}>✕ Cancelled</span>}
    </div>
  );
}

// ─── SOURCE PICKER MODAL ──────────────────────────────────────────────────
// Lets the user pick where a SO line's goods will come from: a stock lot, or a PO.
// Filters intelligently by product (case-insensitive substring match).
function SourcePickerModal({ lineItem, lineIndex, allOrders = [], currentOrderId = null, onCancel, onPick }: any) {
  const [tab, setTab] = useState("STOCK"); // STOCK | PO
  const [filter, setFilter] = useState(lineItem.product || "");

  const productMatch = (p) => !filter || (p || "").toLowerCase().includes(filter.toLowerCase());

  const matchingLots = LOTS.filter(l => productMatch(l.product));
  // PO lines: flatten POs to their items, filter on product
  const matchingPOLines = PO_REFS.flatMap(po =>
    po.items.map(it => ({ ...it, _po: po }))
  ).filter(x => productMatch(x.product));

  function pickLot(lot) {
    onPick({
      sourceType: "STOCK",
      sourceRef: lot.number,
      sourceLineId: null,
      // Auto-fill spec fields from the lot for convenience
      product: lot.product,
      variety: lot.variety || "",
      cnCode: lot.cnCode || "",
      origin: lot.origin,
      size: lot.size,
      quality: lot.quality,
      packaging: lot.packaging,
    });
  }
  function pickPO(poLine) {
    onPick({
      sourceType: "PO",
      sourceRef: poLine._po.number,
      sourceLineId: poLine.id,
      product: poLine.product,
      variety: poLine.variety || "",
      cnCode: poLine.cnCode || "",
      origin: poLine.origin,
      size: poLine.size,
      quality: poLine.quality,
      packaging: poLine.packaging,
      _poExpectedDelivery: poLine._po.expectedDelivery, // signal up to the form for the delivery date warning
    });
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
      <div style={{ background: "#fff", borderRadius: 14, width: "min(820px, 96vw)", maxHeight: "85vh", display: "flex", flexDirection: "column", overflow: "hidden", boxShadow: "0 20px 60px rgba(0,0,0,0.2)" }}>
        <div style={{ padding: "16px 24px", borderBottom: "1px solid #EBEBEB", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700 }}>Pick source for line {lineIndex + 1}</div>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>Source the goods from stock (lot in our warehouse) or from a PO (pre-sold from supplier)</div>
          </div>
          <button onClick={onCancel} style={{ background: "none", border: "none", fontSize: 20, color: "#999", cursor: "pointer" }}>×</button>
        </div>

        <div style={{ padding: "12px 24px", borderBottom: "1px solid #F3F4F6", display: "flex", gap: 8, alignItems: "center" }}>
          <button onClick={() => setTab("STOCK")} style={{ padding: "6px 14px", borderRadius: 7, border: tab === "STOCK" ? "1px solid #0369A1" : "1px solid #E5E7EB", background: tab === "STOCK" ? "#E0F2FE" : "#fff", color: tab === "STOCK" ? "#0369A1" : "#555", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>📦 From Stock ({matchingLots.length})</button>
          <button onClick={() => setTab("PO")} style={{ padding: "6px 14px", borderRadius: 7, border: tab === "PO" ? "1px solid #9D174D" : "1px solid #E5E7EB", background: tab === "PO" ? "#FCE7F3" : "#fff", color: tab === "PO" ? "#9D174D" : "#555", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>🚚 From PO ({matchingPOLines.length})</button>
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ fontSize: 11, color: "#888" }}>Filter by product:</span>
            <Inp value={filter} onChange={e => setFilter(e.target.value)} placeholder="e.g. Carrot" style={{ width: 200 }} />
          </div>
        </div>

        <div style={{ padding: 20, overflowY: "auto", flex: 1, background: "#FAFAFA" }}>
          {tab === "STOCK" && (
            matchingLots.length === 0 ? (
              <div style={{ textAlign: "center", color: "#AAA", padding: 30, fontSize: 13 }}>No matching lots in stock.</div>
            ) : (
              matchingLots.map(lot => {
                const live = lotReservations(lot, allOrders, currentOrderId);
                const isEmpty = live.liveAvailable <= 0;
                return (
                <div key={lot.number} onClick={() => pickLot(lot)}
                  style={{ background: "#fff", border: "1px solid #EBEBEB", borderRadius: 10, padding: "12px 14px", marginBottom: 8, cursor: "pointer", display: "grid", gridTemplateColumns: "140px 1fr 90px 110px 120px", gap: 12, alignItems: "center", opacity: isEmpty ? 0.65 : 1 }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = "#0369A1"}
                  onMouseLeave={e => e.currentTarget.style.borderColor = "#EBEBEB"}>
                  <div>
                    <div style={{ fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12, fontWeight: 700, color: "#0369A1" }}>{lot.number}</div>
                    {(lot as any).status && <span style={{ display: "inline-block", marginTop: 3, fontSize: 9.5, fontWeight: 700, padding: "1px 7px", borderRadius: 5, background: "#F0FDF4", color: "#15803D", border: "1px solid #BBF7D0" }}>{(lot as any).status}</span>}
                  </div>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 600 }}>{lot.product}{(lot as any).variety ? " — " + (lot as any).variety : ""}</div>
                    <div style={{ fontSize: 11, color: "#888" }}>{lot.size} · {lot.origin} · {lot.packaging}{(lot as any).arrivalDate ? ` · arrived ${formatDMY((lot as any).arrivalDate)}` : ""}</div>
                    {live.reservations.length > 0 && (
                      <div style={{ fontSize: 10, color: "#9D174D", marginTop: 3 }}>
                        Reserved: {live.reservations.map(r => `${fmtNum(r.qty)} kg by ${r.soNumber}`).join(" · ")}
                      </div>
                    )}
                  </div>
                  <div><QualityBadge quality={lot.quality} /></div>
                  <div style={{ fontSize: 11, color: "#666" }}>{lot.warehouse}{lot.poRef ? <div style={{ fontSize: 10, color: "#94A3B8", marginTop: 2 }}>from {lot.poRef}</div> : null}</div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 13, fontWeight: 700, color: isEmpty ? "#9CA3AF" : "#16A34A" }}>{fmtNum(live.liveAvailable)} kg</div>
                    <div style={{ fontSize: 10, color: "#888" }}>live available</div>
                    {live.totalReserved > 0 && (
                      <div style={{ fontSize: 9.5, color: "#AAA", marginTop: 1 }}>of {fmtNum(lot.availableKg)} total</div>
                    )}
                  </div>
                </div>
                );
              })
            )
          )}
          {tab === "PO" && (
            matchingPOLines.length === 0 ? (
              <div style={{ textAlign: "center", color: "#AAA", padding: 30, fontSize: 13 }}>No matching POs.</div>
            ) : (
              matchingPOLines.map((line, idx) => {
                const live = poLineReservations(line._po, line, allOrders, currentOrderId);
                const isEmpty = live.liveAvailable <= 0;
                return (
                <div key={`${line._po.number}-${line.id}`} onClick={() => pickPO(line)}
                  style={{ background: "#fff", border: "1px solid #EBEBEB", borderRadius: 10, padding: "12px 14px", marginBottom: 8, cursor: "pointer", display: "grid", gridTemplateColumns: "140px 1fr 90px 120px 120px", gap: 12, alignItems: "center", opacity: isEmpty ? 0.65 : 1 }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = "#9D174D"}
                  onMouseLeave={e => e.currentTarget.style.borderColor = "#EBEBEB"}>
                  <div>
                    <div style={{ fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12, fontWeight: 700, color: "#9D174D" }}>{line._po.number}</div>
                    <span style={{
                      display: "inline-block", marginTop: 3, padding: "1px 6px", borderRadius: 4,
                      fontSize: 9.5, fontWeight: 700, letterSpacing: "0.04em",
                      background: line._po.status === "Draft" ? "#F3F4F6" : "#DBEAFE",
                      color: line._po.status === "Draft" ? "#6B7280" : "#2563EB",
                    }}>{line._po.status}</span>
                  </div>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 600 }}>{line.product}{(line as any).variety ? " — " + (line as any).variety : ""}</div>
                    <div style={{ fontSize: 11, color: "#888" }}>{line.size} · {line.origin} · {line.packaging}</div>
                    <div style={{ fontSize: 10, color: "#AAA", marginTop: 2 }}>Supplier: {line._po.supplierName} · ETA {line._po.expectedDelivery}</div>
                    {live.reservations.length > 0 && (
                      <div style={{ fontSize: 10, color: "#9D174D", marginTop: 3 }}>
                        Reserved: {live.reservations.map(r => `${fmtNum(r.qty)} kg by ${r.soNumber}`).join(" · ")}
                      </div>
                    )}
                  </div>
                  <div><QualityBadge quality={line.quality} /></div>
                  <div style={{ fontSize: 11, color: "#666" }}>—</div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 13, fontWeight: 700, color: isEmpty ? "#9CA3AF" : "#9D174D" }}>{fmtNum(live.liveAvailable)} kg</div>
                    <div style={{ fontSize: 10, color: "#888" }}>live available</div>
                    {live.totalReserved > 0 && (
                      <div style={{ fontSize: 9.5, color: "#AAA", marginTop: 1 }}>of {fmtNum(line.available)} total</div>
                    )}
                  </div>
                </div>
                );
              })
            )
          )}
        </div>
      </div>
    </div>
  );
}

// ─── PRINTED SO DOC ───────────────────────────────────────────────────────
// Bilingual EN/PL, A4, logo top-left. Mirror of PODoc but with sales polarity:
// we are Sprzedawca (seller), client is Nabywca (buyer). No legal clause.
function BiLbl({ en, pl, align = "left" }: any) {
  return (
    <div style={{ textAlign: align as React.CSSProperties["textAlign"], lineHeight: 1.1 }}>
      <div style={{ fontWeight: 700, fontSize: 10 }}>{en}</div>
      <div style={{ fontStyle: "italic", color: "#666", fontSize: 8.5 }}>{pl}</div>
    </div>
  );
}
function PrintLogo() {
  return (
    <div style={{ background: "#fff", display: "inline-block" }}>
      <img src={LOGO_DATA_URL} alt="Marianna" style={{ width: 240, height: "auto", display: "block" }} />
    </div>
  );
}
function SODoc({ order }: any) {
  const total = netTotal(order.items);
  const currency = order.currency || "PLN";
  const paymentDisplay = order.paymentTerms === "Other" ? (order.paymentTermsOther || "Other") : order.paymentTerms;
  const destinationLabel = destinationDisplay(order);

  const meta = [
    { en: "SO No.",             pl: "Nr zamówienia",          value: order.number,             strong: true },
    { en: "Order date",         pl: "Data zamówienia",        value: formatDMY(order.orderDate) },
    { en: "Delivery date",      pl: "Data dostawy",           value: formatDMY(order.deliveryDate) },
    { en: "Incoterm",           pl: "Warunki Incoterms",      value: order.sellIncoterm,       strong: true },
    { en: "Payment",            pl: "Warunki płatności",      value: paymentDisplay },
    { en: "Delivery to",        pl: "Miejsce dostawy",        value: destinationLabel },
    ...(order.importPermitNo ? [{ en: "Import permit no.", pl: "Nr pozwolenia importowego", value: order.importPermitNo, strong: true }] : []),
    ...(order.acidNo ? [{ en: "ACID no.", pl: "Nr ACID", value: order.acidNo, strong: true }] : []),
  ];
  const clientRows = [
    { en: "Name",      pl: "Nazwa",     value: order.client?.name    || "—" },
    { en: "Country",   pl: "Kraj",      value: order.client?.country || "—" },
    { en: "Address",   pl: "Adres",     value: order.client?.address || "—" },
    { en: "NIP / VAT", pl: "NIP / VAT", value: order.client?.nip     || "—" },
    { en: "Contact",   pl: "Kontakt",   value: order.client?.contact || "—" },
  ];

  return (
    <div style={{ fontFamily: "Calibri, Arial, sans-serif", fontSize: 10.5, color: "#111", width: "100%" }}>
      {/* HEADER */}
      <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: 14 }}>
        <tbody>
          <tr>
            <td style={{ width: "35%", verticalAlign: "middle", padding: "4px 0" }}>
              <PrintLogo />
            </td>
            <td style={{ width: "65%", textAlign: "right", verticalAlign: "middle" }}>
              <div style={{ fontSize: 16, fontWeight: 700, lineHeight: 1.1 }}>Sales Order</div>
              <div style={{ fontSize: 13, fontStyle: "italic", color: "#555", marginTop: 2 }}>Zamówienie sprzedaży</div>
            </td>
          </tr>
        </tbody>
      </table>

      {/* META + SELLER */}
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <tbody>
          <tr>
            <td style={{ border: "1px solid #ccc", padding: "8px 10px", width: "50%", verticalAlign: "top" }}>
              {meta.map((r, i) => (
                <div key={i} style={{ display: "flex", alignItems: "baseline", marginBottom: i === meta.length - 1 ? 0 : 4, gap: 8 }}>
                  <div style={{ flex: "0 0 42%" }}>
                    <span style={{ fontWeight: 700, fontSize: 9.5 }}>{r.en}</span>
                    <span style={{ fontStyle: "italic", color: "#777", fontSize: 8.5, marginLeft: 4 }}>{r.pl}</span>
                  </div>
                  <div style={{ fontWeight: r.strong ? 700 : 500, fontSize: r.strong ? 12 : 11 }}>{r.value || "—"}</div>
                </div>
              ))}
            </td>
            <td style={{ border: "1px solid #ccc", padding: "8px 10px", verticalAlign: "top", width: "50%" }}>
              <BiLbl en="Seller" pl="Sprzedawca" />
              <div style={{ marginTop: 4, fontWeight: 700, fontSize: 12 }}>{COMPANY.name}</div>
              <div style={{ fontSize: 11 }}>{COMPANY.person}</div>
              {COMPANY.address.split("\n").map((l, i) => <div key={i} style={{ fontSize: 11 }}>{l}</div>)}
              <div style={{ fontSize: 11, marginTop: 2 }}><span style={{ fontWeight: 600 }}>NIP:</span> {COMPANY.nip}</div>
            </td>
          </tr>
        </tbody>
      </table>

      {/* BUYER */}
      <table style={{ width: "100%", borderCollapse: "collapse", marginTop: -1 }}>
        <thead>
          <tr>
            <th colSpan={2} style={{ border: "1px solid #ccc", background: "#f9f9f9", padding: "6px 10px", textAlign: "left" }}>
              <BiLbl en="Buyer" pl="Nabywca" />
            </th>
          </tr>
        </thead>
        <tbody>
          {clientRows.map(r => (
            <tr key={r.en}>
              <td style={{ border: "1px solid #ccc", padding: "5px 10px", width: "30%", verticalAlign: "top" }}>
                <span style={{ fontWeight: 700, fontSize: 9.5 }}>{r.en}</span>
                <span style={{ fontStyle: "italic", color: "#777", fontSize: 8.5, marginLeft: 4 }}>{r.pl}</span>
              </td>
              <td style={{ border: "1px solid #ccc", padding: "5px 10px", fontWeight: 500 }}>{r.value}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* GOODS TABLE */}
      <table style={{ width: "100%", borderCollapse: "collapse", marginTop: -1 }}>
        <thead>
          <tr>
            <th colSpan={11} style={{ border: "1px solid #ccc", background: "#f9f9f9", padding: "6px 10px", textAlign: "left" }}>
              <BiLbl en="Description of goods" pl="Opis towaru" />
            </th>
          </tr>
          <tr style={{ background: "#f3f3f3" }}>
            {[
              { en: "Product",     pl: "Produkt",      align: "left" },
              { en: "Origin",      pl: "Pochodzenie",  align: "left" },
              { en: "Size",        pl: "Kaliber",      align: "center" },
              { en: "Quality",     pl: "Klasa",        align: "center" },
              { en: "Packaging",   pl: "Opakowanie",   align: "left" },
              { en: "Pallets",     pl: "Palety",       align: "center" },
              { en: "Unit",        pl: "Jedn.",        align: "center" },
              { en: "Qty",         pl: "Ilość",        align: "right" },
              { en: "Unit Price",  pl: "Cena jedn.",   align: "right" },
              { en: "Currency",    pl: "Waluta",       align: "center" },
              { en: "Total",       pl: "Wartość",      align: "right" },
            ].map((h, i) => {
              const headerAlign = h.align as "left" | "center" | "right";
              return (
                <th key={i} style={{ border: "1px solid #ccc", padding: "5px 5px", textAlign: headerAlign, verticalAlign: "bottom" }}>
                  <BiLbl en={h.en} pl={h.pl} align={headerAlign} />
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {order.items.map((item, i) => {
            const lt = ((parseFloat(item.qty) || 0) * (parseFloat(item.unitPrice) || 0)).toFixed(2);
            return (
              <tr key={i}>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", fontWeight: 700 }}>{item.product}{item.variety ? <span style={{ fontWeight: 400 }}> — {item.variety}</span> : null}{item.cnCode ? <div style={{ fontSize: 8.5, fontWeight: 400, color: "#666" }}>CN/HS: {item.cnCode}</div> : null}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px" }}>{item.origin}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "center" }}>{item.size}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "center" }}>Kl. {item.quality}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px" }}>{item.packaging || "—"}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "center" }}>{item.pallets || "—"}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "center" }}>{item.unit || "Kg"}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "right" }}>{parseFloat(item.qty || 0).toLocaleString("pl-PL")}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "right" }}>{parseFloat(item.unitPrice || 0).toFixed(2)}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "center" }}>{order.currency}</td>
                <td style={{ border: "1px solid #ccc", padding: "5px 8px", textAlign: "right", fontWeight: 600 }}>{parseFloat(lt).toLocaleString("pl-PL", { minimumFractionDigits: 2 })}</td>
              </tr>
            );
          })}
          <tr>
            <td colSpan={9} style={{ border: "1px solid #ccc", padding: "6px 8px", verticalAlign: "top" }}>
              <div style={{ fontSize: 9, color: "#777" }}>
                <span style={{ fontWeight: 700, color: "#E05A2B" }}>Notes</span>
                <span style={{ fontStyle: "italic", marginLeft: 4 }}>/ Uwagi</span>
              </div>
              <div style={{ marginTop: 3, fontSize: 10.5, color: "#333", whiteSpace: "pre-wrap" }}>{order.notes || "—"}</div>
            </td>
            <td style={{ border: "1px solid #ccc", padding: "6px 8px", textAlign: "right", background: "#f9f9f9", verticalAlign: "top" }}>
              <BiLbl en="Net Total" pl="Suma netto" align="right" />
            </td>
            <td style={{ border: "1px solid #ccc", padding: "6px 8px", textAlign: "right", fontWeight: 700, fontSize: 12, verticalAlign: "top" }}>
              {total.toLocaleString("pl-PL", { minimumFractionDigits: 2 })} {currency}
            </td>
          </tr>
        </tbody>
      </table>

      {/* SIGNATURES — no legal clause on SO per user request */}
      <table style={{ width: "100%", borderCollapse: "collapse", marginTop: 12 }}>
        <tbody>
          <tr>
            <td style={{ border: "1px solid #ccc", padding: "10px 10px 6px", width: "50%", textAlign: "center", color: "#888" }}>
              <div style={{ height: 14 }} />
              <div style={{ borderTop: "1px solid #555", paddingTop: 3, margin: "0 auto", maxWidth: 220 }}>
                <BiLbl en="Seller signature" pl="Podpis sprzedawcy" align="center" />
              </div>
            </td>
            <td style={{ border: "1px solid #ccc", padding: "10px 10px 6px", width: "50%", textAlign: "center", color: "#888" }}>
              <div style={{ height: 14 }} />
              <div style={{ borderTop: "1px solid #555", paddingTop: 3, margin: "0 auto", maxWidth: 220 }}>
                <BiLbl en="Buyer signature" pl="Podpis nabywcy" align="center" />
              </div>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

// ─── PRINT MODAL ──────────────────────────────────────────────────────────
function PrintModal({ order, onClose }: any) {
  function printDoc() {
    const node = document.getElementById("so-print-doc");
    if (!node) { alert("Print preview not ready"); return; }
    const existing = document.getElementById("so-print-frame");
    if (existing) existing.remove();
    const iframe = document.createElement("iframe");
    iframe.id = "so-print-frame";
    iframe.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0";
    document.body.appendChild(iframe);
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${order.number}</title>
<style>
  @page { size: A4; margin: 12mm; }
  html, body { margin: 0; padding: 0; background: #fff; }
  body { font-family: Calibri, Arial, sans-serif; color: #111; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  #so-print-doc { width: 186mm; margin: 0 auto; }
  table { page-break-inside: avoid; border-collapse: collapse; }
  tr { page-break-inside: avoid; }
  img { max-width: 100%; }
</style></head><body>${node.outerHTML}</body></html>`;
    const doc = iframe.contentDocument || iframe.contentWindow?.document;
    if (!doc) { iframe.remove(); return; }
    doc.open(); doc.write(html); doc.close();
    const fire = () => {
      const prevTitle = document.title; // v6.34.2: restore on afterprint, not 1s
      document.title = order.number || prevTitle;
      const restore = () => { document.title = prevTitle; iframe.remove(); };
      try { iframe.contentWindow?.focus(); const w = iframe.contentWindow as any; if (w) w.onafterprint = restore; iframe.contentWindow?.print(); } catch {}
      setTimeout(() => { if (document.title === (order.number || prevTitle)) restore(); }, 60000);
    };
    const img = doc.querySelector("img");
    if (img && !img.complete) {
      img.addEventListener("load", () => setTimeout(fire, 100));
      img.addEventListener("error", () => setTimeout(fire, 100));
      setTimeout(fire, 2000);
    } else {
      setTimeout(fire, 200);
    }
  }
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
      <div style={{ background: "#fff", borderRadius: 14, width: "min(940px, 96vw)", maxHeight: "92vh", display: "flex", flexDirection: "column", overflow: "hidden", boxShadow: "0 20px 60px rgba(0,0,0,0.2)" }}>
        <div style={{ padding: "16px 24px", borderBottom: "1px solid #EBEBEB", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700 }}>Preview · {order.number}</div>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>A4 format · in the print dialog, set Destination to "Save as PDF"</div>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={printDoc} style={{ padding: "7px 14px", borderRadius: 7, border: "1px solid #2563EB", background: "#2563EB", color: "#fff", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>🖨 Print / Save as PDF</button>
            <button onClick={onClose} style={{ padding: "7px 14px", borderRadius: 7, border: "1px solid #E5E7EB", background: "#fff", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Close</button>
          </div>
        </div>
        <div style={{ padding: 24, overflowY: "auto", background: "#ECECEC" }}>
          <div id="so-print-doc" style={{ background: "#fff", padding: "8mm", boxShadow: "0 2px 12px rgba(0,0,0,0.15)", width: "186mm", margin: "0 auto", boxSizing: "content-box" }}>
            <SODoc order={order} />
          </div>
        </div>
      </div>
    </div>
  );
}


// ─── EMAIL MODAL ──────────────────────────────────────────────────────────
function bestContactEmail(cp: any) {
  const cs = (cp && cp.contacts) || [];
  const withEmail = cs.find((p: any) => p.isPrimary && p.email) || cs.find((p: any) => p.email);
  return (withEmail && withEmail.email) || (cp && cp.email) || "";
}
function EmailModal({ order, contacts = [], onClose }: any) {
  // v6.18.14 (#1): resolve the client email LIVE from Contacts at send time.
  const sid = order && order.client && order.client.id;
  const liveClient = (sid != null) ? (contacts || []).find((c: any) => String(c.id) === String(sid)) : null;
  const recipient = bestContactEmail(liveClient) || order.client?.email || order.client?.contact || "";
  const [subject, setSubject] = useState(`Sales Order ${order.number} — ${COMPANY.name}`);
  const [body, setBody] = useState(`Dear ${order.client?.name || "Sir/Madam"},\n\nPlease find attached our Sales Order confirmation ${order.number} for ${order.items.map(i => `${fmtNum(i.qty)} kg ${i.product}${i.variety ? " " + i.variety : ""}`).join(", ")}.\n\nDelivery date: ${formatDMY(order.deliveryDate) || "TBA"}\nIncoterm: ${order.sellIncoterm}\nPayment: ${order.paymentTerms === "Other" ? order.paymentTermsOther : order.paymentTerms}${order.importPermitNo ? `\nImport permit no.: ${order.importPermitNo}` : ""}${order.acidNo ? `\nACID no.: ${order.acidNo}` : ""}\n\nPlease confirm receipt.\n\nBest regards,\n${COMPANY.name}`);

  function openPrintForPdf() {
    const node = document.getElementById("so-print-doc");
    if (!node) { alert("Print preview not ready — please try again in a moment."); return; }
    const existing = document.getElementById("so-email-print-frame");
    if (existing) existing.remove();
    const iframe = document.createElement("iframe");
    iframe.id = "so-email-print-frame";
    iframe.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0";
    document.body.appendChild(iframe);
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${order.number}</title>
<style>
  @page { size: A4; margin: 12mm; }
  html, body { margin: 0; padding: 0; background: #fff; }
  body { font-family: Calibri, Arial, sans-serif; color: #111; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  #so-print-doc { width: 186mm; margin: 0 auto; }
  table { page-break-inside: avoid; border-collapse: collapse; }
  tr { page-break-inside: avoid; }
  img { max-width: 100%; }
</style></head><body>${node.outerHTML}</body></html>`;
    const doc = iframe.contentDocument || iframe.contentWindow?.document;
    if (!doc) { iframe.remove(); return; }
    doc.open(); doc.write(html); doc.close();
    const fire = () => {
      const prevTitle = document.title; // v6.34.2: restore on afterprint, not 1s
      document.title = order.number || prevTitle;
      const restore = () => { document.title = prevTitle; iframe.remove(); };
      try { iframe.contentWindow?.focus(); const w = iframe.contentWindow as any; if (w) w.onafterprint = restore; iframe.contentWindow?.print(); } catch {}
      setTimeout(() => { if (document.title === (order.number || prevTitle)) restore(); }, 60000);
    };
    const img = doc.querySelector("img");
    if (img && !img.complete) {
      img.addEventListener("load", () => setTimeout(fire, 100));
      img.addEventListener("error", () => setTimeout(fire, 100));
      setTimeout(fire, 2000);
    } else {
      setTimeout(fire, 200);
    }
  }

  function openMailClient() {
    const mailto = `mailto:${encodeURIComponent(recipient)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailto;
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
      <div style={{ background: "#fff", borderRadius: 14, width: 620, maxHeight: "92vh", overflow: "auto", boxShadow: "0 20px 60px rgba(0,0,0,0.2)" }}>
        <div style={{ padding: "16px 24px", borderBottom: "1px solid #EBEBEB", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700 }}>Email SO to {order.client?.name}</div>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>Two-step send · PDF download, then email draft</div>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", fontSize: 20, color: "#999", cursor: "pointer" }}>×</button>
        </div>
        <div style={{ padding: "20px 24px", display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ padding: "12px 14px", background: "#FEF3C7", border: "1px solid #FDE68A", borderRadius: 8, fontSize: 12, color: "#92400E", lineHeight: 1.5 }}>
            <div style={{ fontWeight: 700, marginBottom: 4 }}>⚠ Interim workflow — no backend yet</div>
            Until the email backend is built, sending happens in two steps: save the SO as PDF, then open an email draft and attach the PDF manually.
          </div>
          <div><Lbl>TO</Lbl><Inp value={recipient || "(client email missing in Contacts)"} disabled style={{ background: "#F9FAFB", color: "#666" }} /></div>
          <div><Lbl>SUBJECT</Lbl><Inp value={subject} onChange={e => setSubject(e.target.value)} /></div>
          <div><Lbl>MESSAGE</Lbl><textarea value={body} onChange={e => setBody(e.target.value)} rows={10} style={{ width: "100%", border: "1px solid #E5E7EB", borderRadius: 6, padding: "8px 10px", fontSize: 13, fontFamily: "inherit", outline: "none", resize: "vertical", lineHeight: 1.6 }} /></div>
          <div style={{ position: "absolute", left: -99999, top: 0 }}>
            <div id="so-print-doc" style={{ width: "186mm" }}>
              <SODoc order={order} />
            </div>
          </div>
          <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", borderTop: "1px solid #F3F4F6", paddingTop: 14, marginTop: 4 }}>
            <button onClick={onClose} style={{ padding: "8px 16px", borderRadius: 7, border: "1px solid #E5E7EB", background: "#fff", fontSize: 13, cursor: "pointer" }}>Cancel</button>
            <button onClick={openPrintForPdf} style={{ padding: "8px 16px", borderRadius: 7, border: "1px solid #2563EB", background: "#fff", color: "#2563EB", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>① Save PDF</button>
            <button onClick={openMailClient} disabled={!recipient} title={!recipient ? "Client email missing in Contacts" : ""} style={{ padding: "8px 18px", borderRadius: 7, border: "none", background: recipient ? "#16A34A" : "#D1D5DB", color: "#fff", fontSize: 13, fontWeight: 600, cursor: recipient ? "pointer" : "not-allowed" }}>② Open email draft →</button>
          </div>
        </div>
      </div>
    </div>
  );
}


// ─── INVOICE CREATION MODAL ───────────────────────────────────────────────
// Triggered when an SO transitions to Shipped. Previews the Sales Invoice (SINV)
// that will be created from the SO data and asks the user to confirm.
// User can adjust VAT rate, payment method, and dates before confirming.
//
// Interim behavior (no backend yet): the invoice object is stored in this SO's
// v6.33.0 (A3-6): the canonical invoice is written to the Invoices REGISTER
// (sole owner); the SO keeps only the number in `linkedInvoices`.
// record of the invoice that needs to be created in Fakturownia / the Invoices module.
function InvoiceCreationModal({ order, existingInvoiceNumbers, onCancel, onConfirm }: any) {
  const today = localTodayISO();
  const initial = buildInvoiceFromSO(order, nextSINVNumber(existingInvoiceNumbers || []), today);
  const [invoice, setInvoice] = useState(initial);

  const sf = (k, v) => setInvoice(prev => {
    const next = { ...prev, [k]: v };
    // Recalc VAT/gross on rate or net change
    if (k === "vatRate" || k === "netAmount") {
      const r = parseFloat(k === "vatRate" ? v : next.vatRate) || 0;
      const n = parseFloat(k === "netAmount" ? v : next.netAmount) || 0;
      next.vatAmount = Math.round(n * r) / 100;
      next.grossAmount = Math.round((n + next.vatAmount) * 100) / 100;
      next.netPLN = Math.round(n * (parseFloat(String(next.fxRate)) || 1) * 100) / 100;
      next.grossPLN = Math.round(next.grossAmount * (parseFloat(String(next.fxRate)) || 1) * 100) / 100;
    }
    return next;
  });

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
      <div style={{ background: "#fff", borderRadius: 14, width: "min(720px, 96vw)", maxHeight: "92vh", display: "flex", flexDirection: "column", overflow: "hidden", boxShadow: "0 20px 60px rgba(0,0,0,0.2)" }}>
        <div style={{ padding: "16px 24px", borderBottom: "1px solid #EBEBEB", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700 }}>Issue Sales Invoice from {order.number}</div>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>Goods shipped — review the invoice details and confirm to create the SINV</div>
          </div>
          <button onClick={onCancel} style={{ background: "none", border: "none", fontSize: 20, color: "#999", cursor: "pointer" }}>×</button>
        </div>

        <div style={{ padding: 20, overflowY: "auto", background: "#FAFAFA", flex: 1 }}>
          {/* Backend-phase note */}
          <div style={{ padding: "10px 14px", background: "#FFFBEB", border: "1px solid #FCD34D", borderRadius: 8, marginBottom: 14, fontSize: 11, color: "#92400E", lineHeight: 1.5 }}>
            <strong>Interim flow (no backend yet):</strong> the invoice will be saved on this SO as a "pending" record. When the Invoices module is integrated, it will be created there automatically. For now, also enter it in Fakturownia and link the PDF.
          </div>

          <Card style={{ marginBottom: 12 }}>
            <SectionTitle>INVOICE HEADER</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              <div><Lbl>Invoice number</Lbl><Inp value={invoice.number} onChange={e => sf("number", e.target.value)} /></div>
              <div><Lbl>Type</Lbl><div style={{ padding: "8px 10px", background: "#DCFCE7", color: "#16A34A", borderRadius: 6, fontSize: 12, fontWeight: 700, fontFamily: "ui-monospace, Menlo, monospace" }}>SINV · Sales Invoice (↑ Receivable)</div></div>
              <div><Lbl>Issue date</Lbl><Inp value={invoice.issueDate} onChange={e => sf("issueDate", e.target.value)} type="date" max={localTodayISO()} /></div>
              <div><Lbl>Sale date</Lbl><Inp value={invoice.saleDate} onChange={e => sf("saleDate", e.target.value)} type="date" max={localTodayISO()} /></div>
              <div><Lbl>Due date</Lbl><Inp value={invoice.dueDate} onChange={e => sf("dueDate", e.target.value)} type="date" /></div>
              <div><Lbl>Payment method</Lbl>
                <Sel value={invoice.paymentMethod} onChange={e => sf("paymentMethod", e.target.value)}>
                  {["Transfer", "Cash", "Card", "Compensation", "Prepaid"].map(p => <option key={p}>{p}</option>)}
                </Sel>
              </div>
            </div>
          </Card>

          <Card style={{ marginBottom: 12 }}>
            <SectionTitle>BUYER (NABYWCA)</SectionTitle>
            <div style={{ fontSize: 13, fontWeight: 700 }}>{invoice.counterparty?.name || "—"}</div>
            <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>NIP {invoice.counterparty?.nip || "—"}</div>
            <div style={{ fontSize: 11, color: "#666", marginTop: 2 }}>{invoice.counterparty?.address || "—"}</div>
          </Card>

          <Card style={{ marginBottom: 12 }}>
            <SectionTitle>AMOUNTS · VAT</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 12 }}>
              <div><Lbl>Currency</Lbl><div style={{ padding: "8px 10px", fontSize: 13, fontWeight: 600 }}>{invoice.currency}</div></div>
              <div><Lbl>FX rate to PLN</Lbl><div style={{ padding: "8px 10px", fontSize: 13 }}>{invoice.fxRate}</div></div>
              <div><Lbl>Net</Lbl><div style={{ padding: "8px 10px", fontSize: 13, fontWeight: 600 }}>{fmtMoney(invoice.netAmount, invoice.currency)}</div></div>
              <div>
                <Lbl>VAT rate <span style={{ color: "#D97706" }}>· review</span></Lbl>
                <Sel value={invoice.vatRate} onChange={e => sf("vatRate", parseFloat(e.target.value) || 0)}>
                  {[0, 5, 8, 23].map(r => <option key={r} value={r}>{r}%</option>)}
                </Sel>
              </div>
            </div>
            <div style={{ marginTop: 12, padding: 12, background: "#F9FAFB", borderRadius: 8, display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
              <div><div style={{ fontSize: 10, color: "#888" }}>NET</div><div style={{ fontSize: 14, fontWeight: 600 }}>{fmtMoney(invoice.netAmount, invoice.currency)}</div></div>
              <div><div style={{ fontSize: 10, color: "#888" }}>VAT ({invoice.vatRate}%)</div><div style={{ fontSize: 14, fontWeight: 600 }}>{fmtMoney(invoice.vatAmount, invoice.currency)}</div></div>
              <div><div style={{ fontSize: 10, color: "#888" }}>GROSS / Do zapłaty</div><div style={{ fontSize: 16, fontWeight: 700, color: "#16A34A" }}>{fmtMoney(invoice.grossAmount, invoice.currency)}</div></div>
            </div>
          </Card>

          <Card>
            <SectionTitle>LINES (FROM SO)</SectionTitle>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
              <thead>
                <tr style={{ background: "#F9FAFB" }}>
                  <th style={{ padding: "6px 8px", textAlign: "left", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>PRODUCT</th>
                  <th style={{ padding: "6px 8px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>QTY</th>
                  <th style={{ padding: "6px 8px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>PRICE</th>
                  <th style={{ padding: "6px 8px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>LINE TOTAL</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((it, i) => {
                  const lt = (parseFloat(it.qty) || 0) * (parseFloat(it.unitPrice) || 0);
                  return (
                    <tr key={i} style={{ borderBottom: "1px solid #F3F4F6" }}>
                      <td style={{ padding: "6px 8px" }}>{it.product}{it.variety ? <span style={{ fontWeight: 400, color: "#666" }}> — {it.variety}</span> : null}</td>
                      <td style={{ padding: "6px 8px", textAlign: "right" }}>{fmtNum(it.qty)} kg</td>
                      <td style={{ padding: "6px 8px", textAlign: "right" }}>{fmtMoney(it.unitPrice, order.currency)}</td>
                      <td style={{ padding: "6px 8px", textAlign: "right", fontWeight: 600 }}>{fmtMoney(lt, order.currency)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </Card>
        </div>

        <div style={{ padding: "14px 24px", borderTop: "1px solid #EBEBEB", display: "flex", justifyContent: "flex-end", gap: 10 }}>
          <button onClick={onCancel} style={{ padding: "8px 18px", borderRadius: 7, border: "1px solid #E5E7EB", background: "#fff", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>Cancel — Don't create invoice yet</button>
          <button onClick={() => onConfirm(invoice)} style={{ padding: "8px 20px", borderRadius: 7, border: "none", background: "#16A34A", color: "#fff", fontSize: 13, fontWeight: 600, cursor: "pointer" }}>✓ Create Sales Invoice</button>
        </div>
      </div>
    </div>
  );
}


// ─── ORDER FORM ───────────────────────────────────────────────────────────

// Batch 6b hard gate (SO side): the sale's contract to the CLIENT — sell
// incoterm + a resolved destination — gates confirm/print/email. This is also
// the foundation Phase B stands on: disposition derives from these terms.
function soTermsMissing(o: any): string | null {
  if (!o?.sellIncoterm) return "the sell incoterm";
  const mode = o.destinationMode || ((o.destinationLocationId || o.destinationText) ? "other" : "client");
  if (mode === "client") {
    if (!(o.client?.address || "").trim()) return "the client's registered address (or pick another destination)";
    return null;
  }
  if (!(o.destinationLocationId || (o.destinationText || "").trim())) return `the destination for ${o.sellIncoterm}`;
  return null;
}

function OrderForm({ order, setOrder, productSuggestions = [], allOrders = [], clients = CLIENTS, contacts = [], productCatalog = [], setProductCatalog, onSave, onCancel, onPrint, onEmail }: any) {
  // v6.18.4 (P0-4): merge live counterparty addresses so a client/warehouse added
  // this session shows in the destination picker without a browser refresh.
  const liveLocations = (() => {
    const live = counterpartyLocations(contacts || []).map((l: any) => ({ ...l, type: l.legacyType }));
    const byId = new Map<string, any>();
    [...LOCATIONS, ...live].forEach((l: any) => { if (!byId.has(String(l.id))) byId.set(String(l.id), l); });
    return [...byId.values()];
  })();
  const sf = (k, v) => setOrder(o => ({ ...o, [k]: v }));
  const si = (i, k, v) => setOrder(o => ({ ...o, items: o.items.map((it, idx) => idx === i ? { ...it, [k]: v } : it) }));
  const addItem = () => setOrder(o => ({ ...o, items: [...o.items, { id: nextId(), product: "", variety: "", cnCode: "", origin: "", size: "", quality: "I", unit: "Kg", qty: "", pallets: "", unitPrice: "", sourceType: null, sourceRef: "", sourceLineId: null, packaging: "" }] }));
  const removeItem = (i) => setOrder(o => ({ ...o, items: o.items.filter((_, idx) => idx !== i) }));
  const setClient = (name) => {
    const c = clients.find(c => c.name === name);
    setOrder(o => {
      const next: any = { ...o, client: c || null };
      // v6.10 (#15): the delivery destination defaults to the client's own
      // registered address, unless the user has switched to an "Other" address.
      if ((o.destinationMode || ((o.destinationLocationId || o.destinationText) ? "other" : "client")) === "client") {
        next.destinationMode = "client";
        next.destinationLocationId = null;
        next.destinationText = c?.address || "";
      }
      return next;
    });
  };
  // v6.10 (#15): "client" = deliver to the client's registered address;
  // "other" = a different place (dropdown or free text).
  const destMode = order.destinationMode || ((order.destinationLocationId || order.destinationText) ? "other" : "client");
  const setDestMode = (mode) => {
    // v6.34.2 (module review): "client" fills the registered address; anything else
    // CLEARS the free-text and any picked place, so a stale client address can't
    // linger under a CIF/port choice (item: CIF + client address inconsistency).
    if (mode === "client") setOrder(o => ({ ...o, destinationMode: "client", destinationLocationId: null, destinationText: o.client?.address || "" }));
    else setOrder(o => ({ ...o, destinationMode: "other", destinationLocationId: null, destinationText: "" }));
  };
  // v6.11 (#7): destination guidance must match the chosen Incoterm.
  const incotermDestinationHint = (() => {
    const ic = String(order.sellIncoterm || "").toUpperCase();
    if (ic === "EXW") return "EXW — we don't deliver: the client collects from the supplier or our warehouse, so no destination is required.";
    if (ic === "FCA" || ic === "FOB") return `${ic} — destination is the relay point or the port of departure where we hand the goods over.`;
    if (ic === "CIF" || ic === "CFR") return `${ic} — destination is the port of arrival.`;
    if (ic === "DAP" || ic === "DDP") return `${ic} — destination is the client's address, or another address the client indicates.`;
    return "Select the Sell Incoterm above for destination guidance.";
  })();

  // v6.3.0: live duplicate check for import-document numbers. Import permits and
  // ACID numbers are single-use — flag immediately if another SO already carries them.
  const permitDupes = React.useMemo(() => {
    const result: any = {};
    (["importPermitNo", "acidNo"] as const).forEach(field => {
      const v = String(order[field] || "").trim().toLowerCase();
      if (!v || v === "n/a") return;
      const clash = (allOrders || []).find(p => p.id !== order.id && String(p[field] || "").trim().toLowerCase() === v);
      if (clash) result[field] = clash.number;
    });
    return result;
  }, [order.importPermitNo, order.acidNo, order.id, allOrders]);

  // Source picker state
  const [sourceFor, setSourceFor] = useState(null); // index of item being sourced, or null
  function applySource(idx, patch) {
    const { _poExpectedDelivery, ...rest } = patch;
    setOrder(o => {
      const items = o.items.map((it, i) => i === idx ? { ...it, ...rest } : it);
      // If we just sourced from a PO and SO delivery is before PO ETA, store the PO ETA for the warning
      let _poETAByLine = { ...(o._poETAByLine || {}) };
      if (rest.sourceType === "PO" && _poExpectedDelivery) {
        _poETAByLine[idx] = _poExpectedDelivery;
      } else {
        delete _poETAByLine[idx];
      }
      return { ...o, items, _poETAByLine };
    });
    setSourceFor(null);
  }
  function clearSource(idx) {
    setOrder(o => {
      const items = o.items.map((it, i) => i === idx ? { ...it, sourceType: null, sourceRef: "", sourceLineId: null } : it);
      const _poETAByLine = { ...(o._poETAByLine || {}) };
      delete _poETAByLine[idx];
      return { ...o, items, _poETAByLine };
    });
  }

  // Status lock: once Confirmed+, currency/fx and pricing fields lock to prevent accidental edits
  const lockedStatuses = new Set(["Confirmed", "Reserved", "Loading", "Shipped", "Delivered", "Invoiced", "Closed"]);
  const isLocked = lockedStatuses.has(order.status);

  // Sourcing rule: every line must be sourced (stock lot OR PO in any status) before
  // the SO can move past Draft. This is a hard business rule — we can't promise goods
  // to a client unless we have a concrete procurement plan.
  const sourcing = validateSourcing(order.items);
  const nonDraftStatuses = Object.keys(SO_STATUSES).filter(s => s !== "Draft" && s !== "Cancelled");
  // Is the user currently trying to be in a non-Draft, non-Cancelled status while unsourced?
  const sourcingBlock = !sourcing.allSourced && nonDraftStatuses.includes(order.status);
  const poReadinessIssues = validatePOReadinessForSO(order.items);
  const poReadinessBlock = poReadinessIssues.length > 0 && nonDraftStatuses.includes(order.status);

  // Per-line availability check — does each line have enough stock/PO supply to fulfill it?
  // Aggregates across all matching sources (primary source + any other lot/PO with same product).
  // HARD BLOCK on non-Draft statuses (same as sourcing): can't promise to a client what we can't supply.
  // Batch 1 (G3): memoized — recompute only when the lines or other orders change,
  // not on every keystroke in unrelated fields.
  const availability = useMemo(() => computeLineAvailability(order.items, allOrders, order.id), [order.items, allOrders, order.id]);
  const overageCount = availability.filter(a => a.hasOverage).length;
  const availabilityBlock = overageCount > 0 && nonDraftStatuses.includes(order.status);

  // Same-SO duplicate sources: a set of line indices that share a source with another
  // line in THIS order (e.g. the same PO product assigned twice). Map index -> info.
  const dupSourceGroups = sameSoDuplicateSources(order.items);
  const dupLineIndex = {}; // lineIndex -> { sourceRef, sourceLineId, totalQty, count, others:[idx] }
  Object.values(dupSourceGroups).forEach((g: any) => {
    g.indices.forEach((idx: number) => {
      dupLineIndex[idx] = { sourceRef: g.sourceRef, sourceLineId: g.sourceLineId, sourceType: g.sourceType, totalQty: g.totalQty, count: g.indices.length, others: g.indices.filter((x: number) => x !== idx) };
    });
  });
  const hasDuplicateSources = Object.keys(dupSourceGroups).length > 0;

  // Single combined flag for any rule blocking the current status
  const isBlocked = sourcingBlock || poReadinessBlock || availabilityBlock;

  // PO-ETA-vs-SO-delivery warning: if any line sourced from a PO has ETA after this SO's deliveryDate, surface it
  const deliveryWarnings = [];
  order.items.forEach((it, idx) => {
    if (it.sourceType === "PO" && it.sourceRef) {
      const po = PO_REFS.find(p => p.number === it.sourceRef);
      // v6.4.1 fix: field is expectedDeliveryDate — the old name (expectedDelivery)
      // never existed, so this warning could never fire.
      const poETA = po && ((po as any).expectedDeliveryDate || (po as any).expectedDelivery);
      if (po && order.deliveryDate && poETA && order.deliveryDate < poETA) {
        deliveryWarnings.push({ idx, lineProduct: it.product, poRef: it.sourceRef, poETA });
      }
    }
  });

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
      {sourceFor !== null && (
        <SourcePickerModal
          lineItem={order.items[sourceFor]}
          lineIndex={sourceFor}
          allOrders={allOrders}
          currentOrderId={order.id}
          onCancel={() => setSourceFor(null)}
          onPick={(patch) => applySource(sourceFor, patch)}
        />
      )}
      <div style={{ background: "#fff", borderBottom: "1px solid #EBEBEB", padding: "0 28px", height: 52, display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
        <button onClick={onCancel} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "#2563EB", fontWeight: 500 }}>← Sales Orders</button>
        <div style={{ marginLeft: "auto", display: "flex", gap: 10 }}>
          {onPrint && (() => {
            const isDraft = order.status === "Draft";
            return (
              <button
                onClick={isDraft ? undefined : onPrint}
                disabled={isDraft}
                title={isDraft ? "Confirm the SO first — drafts cannot be printed or shared with clients" : ""}
                style={{
                  padding: "5px 14px", borderRadius: 7,
                  border: "1px solid #E5E7EB",
                  background: isDraft ? "#F9FAFB" : "#fff",
                  color: isDraft ? "#9CA3AF" : "#111",
                  fontSize: 12, fontWeight: 600,
                  cursor: isDraft ? "not-allowed" : "pointer"
                }}>🖨 Print / PDF</button>
            );
          })()}
          {(() => {
            const isDraft = order.status === "Draft";
            return (
              <button
                type="button"
                onClick={isDraft ? undefined : onEmail}
                disabled={isDraft}
                title={isDraft ? "Confirm the SO first — drafts cannot be emailed to clients" : ""}
                style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #E5E7EB", background: isDraft ? "#F9FAFB" : "#fff", color: isDraft ? "#9CA3AF" : "#111", fontSize: 12, fontWeight: 600, cursor: isDraft ? "not-allowed" : "pointer" }}
              >✉ Email Client</button>
            );
          })()}
          <button onClick={onCancel} style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #E5E7EB", background: "#fff", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Cancel</button>
          <button
            onClick={() => onSave(order)}
            disabled={isBlocked}
            title={
              sourcingBlock ? `Cannot save as ${order.status} with unsourced lines — pick sources first or set status back to Draft` :
              poReadinessBlock ? `Cannot save as ${order.status} while a sourced PO is Draft, Cancelled or missing.` :
              availabilityBlock ? `Cannot save as ${order.status} — ${overageCount} line(s) exceed available supply. Reduce qty, change source, or set status back to Draft.` :
              ""
            }
            style={{
              padding: "5px 16px", borderRadius: 7, border: "none",
              background: isBlocked ? "#D1D5DB" : "#111",
              color: "#fff", fontSize: 12, fontWeight: 600,
              cursor: isBlocked ? "not-allowed" : "pointer"
            }}>
            Save SO
          </button>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "28px 32px", background: "#FAFAFA" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto" }}>
          <div style={{ marginBottom: 24 }}>
            <div style={{ fontSize: 20, fontWeight: 700, color: "#111" }}>{order.id ? `Edit ${order.number}` : "New Sales Order"}</div>
            <div style={{ fontSize: 12, color: "#AAA", marginTop: 2 }}>Sell to a client — goods come from stock or pre-sold from a PO</div>
          </div>

          {sourcingBlock && (
            <div style={{ padding: "12px 16px", background: "#FEE2E2", border: "1px solid #FCA5A5", borderRadius: 8, marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
              <div style={{ fontSize: 20 }}>🚫</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#991B1B" }}>Cannot save as {order.status} — {sourcing.unsourcedIndexes.length} line{sourcing.unsourcedIndexes.length === 1 ? " is" : "s are"} unsourced</div>
                <div style={{ fontSize: 11, color: "#991B1B", marginTop: 4, lineHeight: 1.5 }}>
                  Every line item must be sourced from either a stock lot or a purchase order (any status, including Draft) before this SO can move past Draft.
                  {sourcing.unsourcedIndexes.length > 0 && (
                    <span> Unsourced: line{sourcing.unsourcedIndexes.length === 1 ? "" : "s"} <strong>{sourcing.unsourcedIndexes.map(i => i + 1).join(", ")}</strong>.</span>
                  )}
                </div>
              </div>
            </div>
          )}

          {poReadinessBlock && (
            <div style={{ padding: "12px 16px", background: "#FEE2E2", border: "1px solid #FCA5A5", borderRadius: 8, marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
              <div style={{ fontSize: 20 }}>🚫</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#991B1B" }}>Cannot save as {order.status} — source PO is not confirmed</div>
                <div style={{ fontSize: 11, color: "#991B1B", marginTop: 4, lineHeight: 1.5 }}>
                  A Sales Order cannot be confirmed/reserved/shipped while it refers to a Purchase Order in Draft, Cancelled or missing status. Blocked: <strong>{poReadinessIssues.map((x: any) => `${x.poRef} (${x.status})`).join(", ")}</strong>.
                </div>
              </div>
            </div>
          )}

          {overageCount > 0 && (
            availabilityBlock ? (
              <div style={{ padding: "12px 16px", background: "#FEE2E2", border: "1px solid #FCA5A5", borderRadius: 8, marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
                <div style={{ fontSize: 20 }}>🚫</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "#991B1B" }}>
                    Cannot save as {order.status} — {overageCount} line{overageCount === 1 ? "" : "s"} exceed available supply
                  </div>
                  <div style={{ fontSize: 11, color: "#991B1B", marginTop: 4, lineHeight: 1.5 }}>
                    You cannot confirm a Sales Order while it promises more goods than we can supply. For each flagged line, either reduce qty, switch to a source with more available stock or PO supply, or arrange more procurement (a new or larger PO). To save without confirming, set status back to Draft.
                  </div>
                </div>
              </div>
            ) : (
              <div style={{ padding: "12px 16px", background: "#FFFBEB", border: "1px solid #FCD34D", borderRadius: 8, marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
                <div style={{ fontSize: 20 }}>⚠️</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "#92400E" }}>
                    {overageCount} line{overageCount === 1 ? "" : "s"} exceed available supply (Draft only)
                  </div>
                  <div style={{ fontSize: 11, color: "#92400E", marginTop: 4, lineHeight: 1.5 }}>
                    This SO is over-allocated. You can keep it as a Draft while procurement scales up supply, but it cannot be Confirmed in this state.
                  </div>
                </div>
              </div>
            )
          )}

          {/* Order details */}
          <Card style={{ marginBottom: 16 }}>
            <SectionTitle>ORDER DETAILS</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 14 }}>
              <div>
                <Lbl>SO number <span style={{ color: "#16A34A", fontWeight: 500 }}>· system number{!order.id ? ", auto-generated" : ""}</span></Lbl>
                {/* BP-18: controlled document id — display/copy only. */}
                <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 11px", border: "1px solid #E5E7EB", borderRadius: 8, background: "#F8FAFC", fontFamily: "ui-monospace, Menlo, monospace", fontSize: 13, fontWeight: 700, color: "#334155" }}>
                  <span>{order.number || "SO-2026-…"}</span>
                  <button type="button" onClick={() => { try { navigator.clipboard.writeText(order.number || ""); } catch {} }} title="Copy SO number" style={{ marginLeft: "auto", border: "1px solid #E5E7EB", background: "#fff", borderRadius: 6, padding: "2px 8px", fontSize: 11, cursor: "pointer", fontWeight: 700, color: "#64748B" }}>Copy</button>
                </div>
              </div>
              <div>
                <Lbl>Order date</Lbl>
                <Inp value={order.orderDate} onChange={e => sf("orderDate", e.target.value)} type="date" title="The date the SO was created/agreed with the client" />
              </div>
              <div>
                <Lbl>Expected delivery date</Lbl>
                <Inp value={order.deliveryDate} onChange={e => sf("deliveryDate", e.target.value)} type="date" title="When the goods are expected to reach the agreed point" />
                {/* FB-14: redundant 'means' dropdown removed. */}
              </div>
              <div>
                <Lbl>Actual delivery</Lbl>
                {/* BP-17: not typed here — comes from the linked Shipment delivery event
                    (or the dispatch/collection event for EXW). Read-only. */}
                <div style={{ padding: "9px 11px", border: "1px dashed #E5E7EB", borderRadius: 8, background: "#FAFAFA", fontSize: 12.5, color: order.actualDeliveryDate ? "#334155" : "#9CA3AF" }}>
                  {order.actualDeliveryDate ? `${order.actualDeliveryDate} · from shipment` : ((order.linkedShipments?.length || 0) ? "Pending shipment delivery" : "No linked shipment")}
                </div>
                <div style={{ fontSize: 10, color: "#AAA", marginTop: 3, lineHeight: 1.4 }}>{order.status === "Delivered" ? "Fill in the date goods reached the client" : "Set status to Delivered to enable"}</div>
              </div>
              <div style={{ order: -1 }}><Lbl>Status</Lbl>
                <Sel value={order.status || "Draft"} onChange={e => sf("status", e.target.value)} disabled={order.status === "Cancelled"}
                  title={order.status === "Cancelled" ? "This SO is cancelled — read-only and can't be reactivated." : ""}
                  style={{ borderLeft: `4px solid ${(SO_STATUSES[order.status || "Draft"] || {}).color || "#9CA3AF"}`, fontWeight: 700, color: (SO_STATUSES[order.status || "Draft"] || {}).color || "#111" }}>
                  {Object.keys(SO_STATUSES).map(s => {
                    // Draft and Cancelled are always available; everything else requires all lines to be
                    // (a) sourced AND (b) have enough combined available qty to cover the demanded qty.
                    if (s === "Draft" || s === "Cancelled") return <option key={s} value={s}>{s}</option>;
                    const needsSource = !sourcing.allSourced;
                    const needsSupply = overageCount > 0;
                    const needsPOReady = poReadinessIssues.length > 0;
                    const disabled = needsSource || needsSupply || needsPOReady;
                    const reason = needsSource && needsSupply ? "  — needs sourcing + supply"
                      : needsSource ? "  — needs sourcing"
                      : needsSupply ? "  — short on supply"
                      : needsPOReady ? "  — PO not confirmed"
                      : "";
                    return <option key={s} value={s} disabled={disabled}>{s}{reason}</option>;
                  })}
                </Sel>
                {(!sourcing.allSourced || overageCount > 0 || poReadinessIssues.length > 0) && (
                  <div style={{ fontSize: 10, color: "#D97706", marginTop: 3, lineHeight: 1.4 }}>
                    {!sourcing.allSourced && (
                      <div>{sourcing.unsourcedIndexes.length} line{sourcing.unsourcedIndexes.length === 1 ? "" : "s"} unsourced</div>
                    )}
                    {poReadinessIssues.length > 0 && (
                      <div>{poReadinessIssues.length} line{poReadinessIssues.length === 1 ? "" : "s"} sourced from a Draft/Cancelled/missing PO</div>
                    )}
                    {overageCount > 0 && (
                      <div>{overageCount} line{overageCount === 1 ? "" : "s"} short on supply</div>
                    )}
                    <div style={{ marginTop: 2 }}>only Draft / Cancelled available</div>
                  </div>
                )}
              </div>
              <div style={{ gridColumn: "span 3" }}>
                <Lbl>Client</Lbl>
                <Sel value={order.client?.name || ""} onChange={e => setClient(e.target.value)}>
                  <option value="">— select —</option>
                  {clients.map(c => <option key={c.id} value={c.name}>{c.name} {c.country ? `· ${c.country}` : ""} {c.nip ? `(NIP ${c.nip})` : ""}</option>)}
                </Sel>
              </div>
              <div>
                <Lbl>Payment terms</Lbl>
                <Sel value={order.paymentTerms || ""} onChange={e => sf("paymentTerms", e.target.value)}>
                  {PAYMENT_TERMS.map(p => <option key={p}>{p}</option>)}
                </Sel>
                {order.paymentTerms === "Other" && (
                  <Inp value={order.paymentTermsOther} onChange={e => sf("paymentTermsOther", e.target.value)} placeholder="Specify terms…" style={{ marginTop: 6 }} />
                )}
              </div>
              <div style={{ gridColumn: "span 2" }}>
                <Lbl>Import permit no. <span style={{ color: "#AAA", fontWeight: 400 }}>· client-country import licence</span></Lbl>
                <Inp value={order.importPermitNo === "N/A" ? "" : (order.importPermitNo || "")} onChange={e => sf("importPermitNo", e.target.value)} placeholder={order.importPermitNo === "N/A" ? "Not applicable" : "e.g. IP-2026-00871"} disabled={order.importPermitNo === "N/A"} />
                <label style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11, color: "#666", marginTop: 4, cursor: "pointer" }}>
                  <input type="checkbox" checked={order.importPermitNo === "N/A"} onChange={e => sf("importPermitNo", e.target.checked ? "N/A" : "")} /> Not applicable
                </label>
                {permitDupes.importPermitNo && (
                  <div style={{ fontSize: 10, color: "#DC2626", marginTop: 3, fontWeight: 600 }}>⚠ Already used on {permitDupes.importPermitNo}</div>
                )}
              </div>
              <div style={{ gridColumn: "span 2" }}>
                <Lbl>ACID no. <span style={{ color: "#AAA", fontWeight: 400 }}>· Egypt Advance Cargo Information Declaration</span></Lbl>
                <Inp value={order.acidNo === "N/A" ? "" : (order.acidNo || "")} onChange={e => sf("acidNo", e.target.value)} placeholder={order.acidNo === "N/A" ? "Not applicable" : "19-digit ACID"} disabled={order.acidNo === "N/A"} />
                <label style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 11, color: "#666", marginTop: 4, cursor: "pointer" }}>
                  <input type="checkbox" checked={order.acidNo === "N/A"} onChange={e => sf("acidNo", e.target.checked ? "N/A" : "")} /> Not applicable
                </label>
                {permitDupes.acidNo && (
                  <div style={{ fontSize: 10, color: "#DC2626", marginTop: 3, fontWeight: 600 }}>⚠ Already used on {permitDupes.acidNo}</div>
                )}
              </div>
            </div>
          </Card>

          {/* Incoterm + destination */}
          <Card style={{ marginBottom: 16 }}>
            <SectionTitle>INCOTERM · DELIVERY</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 14 }}>
              <div>
                <Lbl>Sell Incoterm</Lbl>
                <Sel value={order.sellIncoterm || ""} onChange={e => sf("sellIncoterm", e.target.value)} disabled={isLocked}>
                  <option value="">— select —</option>
                  {INCOTERMS_SELL.map(i => <option key={i.code} value={i.code}>{i.code}</option>)}
                </Sel>
                {order.sellIncoterm && (
                  <div style={{ fontSize: 10.5, color: "#888", marginTop: 4, lineHeight: 1.4 }}>
                    {INCOTERMS_SELL.find(i => i.code === order.sellIncoterm)?.label}
                  </div>
                )}
              </div>
              <div>
                <Lbl>Destination <span style={{ color: "#BBB", fontWeight: 400 }}>· follows sell incoterm</span></Lbl>
                <div style={{ fontSize: 10.5, color: order.sellIncoterm ? "#2563EB" : "#888", margin: "2px 0 6px", lineHeight: 1.4 }}>{incotermDestinationHint}</div>
                {(() => {
                  // FB-11: the destination options adapt to the sell incoterm — the term decides
                  // where WE deliver, so we surface the right place type first.
                  const ic = String(order.sellIncoterm || "").toUpperCase();
                  const portLed = ["CIF", "CFR", "FOB", "FCA"].includes(ic);
                  const clientLed = ["DAP", "DDP"].includes(ic);
                  const whLed = ic === "EXW";
                  return (
                <Sel value={destMode} onChange={e => setDestMode(e.target.value)}>
                  <option value="client">Client's registered address{clientLed ? " (recommended)" : ""}</option>
                  <option value="other">{portLed ? "Port / named place (recommended)" : whLed ? "Our warehouse (EXW pickup)" : "Other address (specify below)"}</option>
                </Sel>
                  );
                })()}
                {destMode === "client" ? (
                  <div style={{ marginTop: 8, padding: "9px 11px", borderRadius: 8, border: "1px solid #E5E7EB", background: "#FAFAFA", fontSize: 12, color: "#444", lineHeight: 1.45 }}>
                    {order.client ? (
                      order.client.address
                        ? <><strong>{order.client.name}</strong><div style={{ color: "#666", marginTop: 2 }}>{order.client.address}{order.client.country ? `, ${order.client.country}` : ""}</div></>
                        : <span style={{ color: "#B45309" }}>This client has no address on file — add one in Counterparties, or choose “Other address”.</span>
                    ) : (
                      <span style={{ color: "#888" }}>Select the client above — the delivery destination defaults to their registered address.</span>
                    )}
                  </div>
                ) : (
                  <>
                    {(() => {
                      const ic = String(order.sellIncoterm || "").toUpperCase();
                      const portGroup = (<optgroup key="port" label="⚓ Port / terminal (FOB/CFR/CIF)">{liveLocations.filter((l: any) => l.type === "PORT").map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}</optgroup>);
                      const clientGroup = (<optgroup key="client" label="🎯 Client Site / DC">{liveLocations.filter((l: any) => l.type === "CLIENT").map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}</optgroup>);
                      const whGroup = (<optgroup key="wh" label="🏢 Our Warehouse (EXW pickup)">{liveLocations.filter((l: any) => l.type === "OWN").map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}</optgroup>);
                      // FB-11: lead with the incoterm-relevant place type.
                      const order2 = ["CIF","CFR","FOB","FCA"].includes(ic) ? [portGroup, clientGroup, whGroup]
                        : ic === "EXW" ? [whGroup, clientGroup, portGroup]
                        : [clientGroup, portGroup, whGroup];
                      return (
                        <Sel value={order.destinationLocationId || ""} onChange={e => { const id = parseInt(e.target.value) || null; setOrder(o => ({ ...o, destinationLocationId: id, destinationText: (id && (o.destinationText || "") === (o.client?.address || "")) ? "" : o.destinationText })); }} style={{ marginTop: 8 }}>
                          <option value="">— select a known place —</option>
                          {order2}
                        </Sel>
                      );
                    })()}
                    <Inp
                      value={order.destinationText || ""}
                      onChange={e => sf("destinationText", e.target.value)}
                      placeholder="…or type the exact delivery address (free text)"
                      style={{ marginTop: 6 }}
                    />
                    <div style={{ fontSize: 10.5, color: "#888", marginTop: 4, lineHeight: 1.4 }}>
                      Pick a known place, or type the exact address (relay, port, or client site as the Incoterm requires). Free text takes precedence on the printed SO.
                    </div>
                  </>
                )}
              </div>
            </div>
          </Card>

          {/* Currency */}
          <Card style={{ marginBottom: 16 }}>
            <SectionTitle>CURRENCY{isLocked && <span style={{ marginLeft: 8, fontSize: 10, color: "#D97706", fontWeight: 600 }}>🔒 locked at {order.status}</span>}</SectionTitle>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 2fr", gap: 14 }}>
              <div><Lbl>Currency</Lbl>
                <Sel value={order.currency} onChange={e => sf("currency", e.target.value)} disabled={isLocked}>
                  {CURRENCIES.map(c => <option key={c}>{c}</option>)}
                </Sel>
              </div>
              <div><Lbl>FX rate to PLN</Lbl>
                <Inp value={order.fxRate ?? ""} onChange={e => sf("fxRate", e.target.value)} type="number" disabled={isLocked} />
                {order.fxLockedAt && <div style={{ fontSize: 10, color: "#888", marginTop: 3 }}>Locked {order.fxLockedAt}</div>}
              </div>
            </div>
          </Card>

          {/* Delivery date warnings */}
          {deliveryWarnings.length > 0 && (
            <div style={{ padding: "10px 14px", background: "#FFFBEB", border: "1px solid #FDE68A", borderRadius: 8, marginBottom: 16 }}>
              <div style={{ fontSize: 12, fontWeight: 700, color: "#92400E", marginBottom: 4 }}>⚠ Delivery date is before PO arrival</div>
              {deliveryWarnings.map(w => (
                <div key={w.idx} style={{ fontSize: 11, color: "#92400E" }}>
                  Line {w.idx + 1} ({w.lineProduct}) is sourced from {w.poRef} which arrives <strong>{w.poETA}</strong>, but SO delivery is set to <strong>{order.deliveryDate}</strong>. Consider pushing SO delivery later.
                </div>
              ))}
            </div>
          )}

          {hasDuplicateSources && (
            <div style={{ padding: "10px 14px", background: "#FFFBEB", border: "1px solid #FDE68A", borderRadius: 8, marginBottom: 16 }}>
              <div style={{ fontSize: 12, fontWeight: 700, color: "#92400E", marginBottom: 4 }}>⚠ Same source assigned to more than one line</div>
              {Object.values(dupSourceGroups).map((g: any, gi) => (
                <div key={gi} style={{ fontSize: 11, color: "#92400E" }}>
                  Lines {g.indices.map((x: number) => x + 1).join(", ")} all draw from <strong>{g.sourceRef}</strong>{g.sourceType === "PO" ? ` (line ${g.sourceLineId})` : ""} — combined <strong>{fmtNum(g.totalQty)} kg</strong>. If this is one physical product, you may be assigning it twice; merge the lines or pick a different source.
                </div>
              ))}
            </div>
          )}

          {/* Line items */}
          <Card style={{ marginBottom: 16 }}>
            <SectionTitle right={<div style={{ display: "flex", gap: 6 }}>
              <button onClick={() => { const idx = order.items.length; addItem(); setTimeout(() => setSourceFor(idx), 0); }} style={{ padding: "4px 12px", borderRadius: 6, border: "none", background: "#0369A1", color: "#fff", fontSize: 11, fontWeight: 700, cursor: "pointer" }} title="Add a line sourced from a PO or stock — product, variety, packaging, origin, size and quality are copied automatically; you set only price, quantity and pallets.">+ Add from PO / stock</button>
              <button onClick={addItem} style={{ padding: "4px 10px", borderRadius: 6, border: "1px solid #16A34A", background: "#fff", color: "#16A34A", fontSize: 11, fontWeight: 600, cursor: "pointer" }} title="Add an empty line to fill in manually">+ Blank line</button>
            </div>}>LINE ITEMS ({order.items.length})</SectionTitle>
            <datalist id="so-product-suggestions">
              {productSuggestions.map(p => <option key={p} value={p} />)}
            </datalist>
            {order.items.map((it, i) => {
              const lineTotal = (parseFloat(it.qty) || 0) * (parseFloat(it.unitPrice) || 0);
              const lineNeedsSource = !it.sourceType || !it.sourceRef;
              const lineIsBlocking = lineNeedsSource && nonDraftStatuses.includes(order.status);
              const avail = availability[i] || {};
              const showAvail = it.sourceType && it.sourceRef && avail.lineQty > 0;
              const lineOverageBlocks = avail.hasOverage && nonDraftStatuses.includes(order.status);
              return (
                <div key={i} style={{
                  marginBottom: 12, padding: 12, borderRadius: 8,
                  background: lineIsBlocking || lineOverageBlocks ? "#FEF2F2" : (avail.hasOverage ? "#FFFBEB" : "#FAFAFA"),
                  border: lineIsBlocking || lineOverageBlocks ? "1px solid #FCA5A5" : (avail.hasOverage ? "1px solid #FCD34D" : "1px solid #F3F4F6")
                }}>
                  {/* Source bar */}
                  <div style={{
                    display: "flex", alignItems: "center", gap: 10, marginBottom: 10, padding: "6px 10px", borderRadius: 6,
                    background: it.sourceType
                      ? (it.sourceType === "STOCK" ? "#E0F2FE" : "#FCE7F3")
                      : (lineIsBlocking ? "#FEE2E2" : "#FEF3C7")
                  }}>
                    <span style={{ fontSize: 11, fontWeight: 700, color: lineIsBlocking ? "#991B1B" : "#444" }}>
                      {lineIsBlocking ? "⚠ Source required:" : "Source:"}
                    </span>
                    <SourceBadge sourceType={it.sourceType} sourceRef={it.sourceRef} supplierName={it.sourceType === "PO" ? supplierNameForPO(it.sourceRef) : ""} />
                    <button onClick={() => setSourceFor(i)} style={{
                      padding: "3px 10px", borderRadius: 5,
                      border: lineIsBlocking ? "1px solid #991B1B" : "1px solid #E5E7EB",
                      background: lineIsBlocking ? "#991B1B" : "#fff",
                      color: lineIsBlocking ? "#fff" : "#111",
                      fontSize: 11, fontWeight: 600, cursor: "pointer"
                    }}>
                      {it.sourceType ? "Change source" : "Pick source →"}
                    </button>
                    {it.sourceType && (
                      <button onClick={() => clearSource(i)} title="Remove the source link from this line" style={{ padding: "3px 10px", borderRadius: 5, border: "1px solid #FECACA", background: "#FEF2F2", color: "#DC2626", fontSize: 11, fontWeight: 600, cursor: "pointer" }}>✕ Clear source</button>
                    )}
                    <div style={{ marginLeft: "auto", fontSize: 10.5, color: lineIsBlocking ? "#991B1B" : "#777" }}>
                      {lineIsBlocking
                        ? `Required to save as ${order.status}`
                        : (!it.sourceType && "Pick a stock lot or PO this line will draw from")}
                    </div>
                  </div>

                  {/* Product mismatch warning — fires if the picked source's product
                      doesn't match this line's product (user picked the wrong lot/PO) */}
                  {avail.primaryProductMismatch && (
                    <div style={{
                      display: "flex", alignItems: "center", gap: 10, marginBottom: 10, padding: "6px 10px", borderRadius: 6,
                      background: "#FEE2E2", border: "1px solid #FCA5A5", fontSize: 11,
                    }}>
                      <span style={{ fontWeight: 700, color: "#991B1B" }}>⚠ Product mismatch:</span>
                      <span style={{ color: "#991B1B" }}>
                        This line is <strong>{it.product || "(no product)"}</strong> but the picked source ({it.sourceRef}) is a different product. Pick a source whose product matches.
                      </span>
                    </div>
                  )}

                  {/* Duplicate-source warning — fires if another line in THIS SAME order
                      already draws from this exact source (same PO line or same lot). */}
                  {dupLineIndex[i] && (
                    <div style={{
                      display: "flex", alignItems: "center", gap: 10, marginBottom: 10, padding: "6px 10px", borderRadius: 6,
                      background: "#FEF3C7", border: "1px solid #FCD34D", fontSize: 11,
                    }}>
                      <span style={{ fontWeight: 700, color: "#92400E" }}>⚠ Same source used twice:</span>
                      <span style={{ color: "#92400E" }}>
                        {dupLineIndex[i].count} lines in this order draw from <strong>{dupLineIndex[i].sourceRef}</strong>{dupLineIndex[i].sourceType === "PO" ? ` (line ${dupLineIndex[i].sourceLineId})` : ""} — combined {fmtNum(dupLineIndex[i].totalQty)} kg. If this is one physical product, you may be assigning it twice. Merge the lines or pick a different source.
                      </span>
                    </div>
                  )}

                  {/* Availability strip — shows when the line is sourced and has a qty */}
                  {showAvail && (
                    <div style={{
                      display: "flex", alignItems: "center", gap: 12, marginBottom: 10, padding: "6px 10px", borderRadius: 6,
                      background: lineOverageBlocks ? "#FEE2E2" : (avail.hasOverage ? "#FEF3C7" : "#F9FAFB"),
                      border: lineOverageBlocks ? "1px solid #FCA5A5" : (avail.hasOverage ? "1px solid #FCD34D" : "1px solid #F3F4F6"),
                      fontSize: 11,
                    }}>
                      <span style={{ fontWeight: 700, color: lineOverageBlocks ? "#991B1B" : (avail.hasOverage ? "#92400E" : "#555") }}>
                        {lineOverageBlocks ? "🚫 Insufficient supply:" : avail.hasOverage ? "⚠ Availability:" : "Availability:"}
                      </span>
                      <span style={{ color: "#444" }}>
                        Demand <strong>{fmtNum(avail.lineQty)} kg</strong>
                      </span>
                      <span style={{ color: "#AAA" }}>·</span>
                      <span style={{ color: "#444" }}>
                        On {it.sourceType === "STOCK" ? "lot" : "PO line"} <strong>{fmtNum(avail.primaryAvailable)} kg</strong>
                      </span>
                      {avail.otherSourcesAvailable > 0 && (
                        <>
                          <span style={{ color: "#AAA" }}>+</span>
                          <span style={{ color: "#444" }}>
                            Other sources <strong>{fmtNum(avail.otherSourcesAvailable)} kg</strong>
                            <span style={{ color: "#888", fontSize: 10 }}>
                              {avail.otherStockKg > 0 && ` (📦 ${fmtNum(avail.otherStockKg)}`}
                              {avail.otherStockKg > 0 && avail.otherPOKg > 0 && ` + `}
                              {avail.otherPOKg > 0 && `🚚 ${fmtNum(avail.otherPOKg)}`}
                              {(avail.otherStockKg > 0 || avail.otherPOKg > 0) && `)`}
                            </span>
                          </span>
                        </>
                      )}
                      <span style={{ color: "#AAA" }}>=</span>
                      <span style={{ color: lineOverageBlocks ? "#991B1B" : (avail.hasOverage ? "#92400E" : "#16A34A"), fontWeight: 600 }}>
                        Combined <strong>{fmtNum(avail.combinedAvailable)} kg</strong>
                      </span>
                      {avail.hasOverage && (
                        <span style={{ marginLeft: "auto", fontWeight: 700, color: lineOverageBlocks ? "#991B1B" : "#92400E" }}>
                          {lineOverageBlocks ? `Blocks ${order.status} — short by ${fmtNum(avail.overage)} kg` : `Short by ${fmtNum(avail.overage)} kg`}
                        </span>
                      )}
                    </div>
                  )}
                  <div style={{ display: "grid", gridTemplateColumns: "1.8fr 0.9fr 0.8fr 0.9fr 1.1fr 1fr 1fr 1.3fr 34px", gap: 8, alignItems: "end" }}>
                    <div>
                      <Lbl>Item / Variety {it.sourceType && it.sourceRef ? <span style={{ color: "#2563EB", fontWeight: 400 }}>· from {it.sourceType === "PO" ? "PO" : "stock"}</span> : null}</Lbl>
                      {it.sourceType && it.sourceRef
                        ? <div style={{ border: "1px solid #E5E7EB", borderRadius: 6, padding: "7px 9px", fontSize: 12.5, background: "#F9FAFB", color: "#374151", minHeight: 18 }} title="Inherited from the linked source — clear the source link to change the product">{it.product || "—"}{it.variety ? ` — ${it.variety}` : ""}</div>
                        : <ItemVarietyPicker catalog={productCatalog} setCatalog={setProductCatalog} item={it.product || ""} variety={it.variety || ""} onItem={(v: string) => si(i, "product", v)} onVariety={(v: string) => si(i, "variety", v)} />}
                    </div>
                    <div><Lbl>Origin</Lbl><Inp value={it.origin} onChange={e => si(i, "origin", e.target.value)} placeholder="Poland" /></div>
                    <div><Lbl>Size</Lbl><Inp value={it.size} onChange={e => si(i, "size", e.target.value)} placeholder="70-80" /></div>
                    <div><Lbl>Quality</Lbl><Sel value={it.quality} onChange={e => si(i, "quality", e.target.value)}>{QUALITY_GRADES.map(q => <option key={q}>{q}</option>)}</Sel></div>
                    <div><Lbl>CN / HS code</Lbl><Inp value={it.cnCode || ""} onChange={e => si(i, "cnCode", e.target.value)} placeholder="e.g. 08081080" title="Customs nomenclature code — printed on the SO and used on the Fakturownia invoice. Inherited from the PO when the line is sourced from one." disabled={!!(it.sourceType && it.sourceRef)} /></div>
                    <div><Lbl>Qty (kg)</Lbl><Inp type="number" value={it.qty} onChange={e => si(i, "qty", e.target.value)} placeholder="e.g. 8000" /></div>
                    <div><Lbl>Sell price</Lbl><Inp type="number" value={it.unitPrice} onChange={e => si(i, "unitPrice", e.target.value)} placeholder="e.g. 2.80" disabled={isLocked} /></div>
                    <div style={{ minWidth: 0 }}><Lbl>Line total</Lbl><div style={{ padding: "8px 4px", fontSize: 12.5, fontWeight: 700, color: "#111", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", fontVariantNumeric: "tabular-nums" }} title={lineTotal.toLocaleString("pl-PL", { minimumFractionDigits: 2 })}>{lineTotal.toLocaleString("pl-PL", { minimumFractionDigits: 2 })}</div></div>
                    <button onClick={() => removeItem(i)} disabled={order.items.length <= 1} style={{ height: 33, padding: "0 6px", border: "1px solid #FECACA", borderRadius: 6, background: "#fff", color: "#DC2626", fontSize: 11, cursor: order.items.length <= 1 ? "not-allowed" : "pointer", opacity: order.items.length <= 1 ? 0.4 : 1 }}>🗑</button>
                  </div>
                  <div style={{ marginTop: 8, display: "grid", gridTemplateColumns: "1fr 200px", gap: 10 }}>
                    <div>
                      <Lbl>Packaging</Lbl>
                      <Inp value={it.packaging} onChange={e => si(i, "packaging", e.target.value)} placeholder="13 kg wooden box / 5 kg carton / 10 kg mesh bag" />
                    </div>
                    <div>
                      <Lbl>Pallets (for this sale)</Lbl>
                      <Inp type="number" value={it.pallets ?? ""} onChange={e => si(i, "pallets", e.target.value)} placeholder="e.g. 12" />
                    </div>
                  </div>
                </div>
              );
            })}
            <div style={{ marginTop: 14, padding: 14, background: "#F9FAFB", borderRadius: 8, display: "flex", justifyContent: "flex-end", gap: 24 }}>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: 10, color: "#888" }}>NET TOTAL</div>
                <div style={{ fontSize: 18, fontWeight: 700 }}>{fmtMoney(netTotal(order.items), order.currency)}</div>
              </div>
            </div>
          </Card>

          {/* Notes */}
          <Card>
            <SectionTitle>NOTES</SectionTitle>
            <textarea value={order.notes || ""} onChange={e => sf("notes", e.target.value)} rows={3} style={{ width: "100%", border: "1px solid #E5E7EB", borderRadius: 6, padding: "8px 10px", fontSize: 13, fontFamily: "inherit", outline: "none", background: "#fff", resize: "vertical" }} placeholder="Special instructions, pallet labels, etc." />
          </Card>
        </div>
      </div>
    </div>
  );
}


// ─── ORDER DETAIL ─────────────────────────────────────────────────────────
function OrderDetail({ order, soInvoices = [], onBack, onEdit, onPrint, onEmail, onDelete, onIssueInvoice, onRecordCollection = null, onRecordClientClaim = null, fktConfigured = false, onMatchInvoices = () => {}, fktMatching = false, fktMatchMsg = null, allOrders = [], lots = [], pos = [], shipments = [], operationalCosts = [], userRole = "General Manager", userName = "" }: any) {
  // BP-49: linked records are COMPUTED from the documents that reference this SO,
  // not read from stored arrays (which drift).
  const computedLinks = computedSOLinks(order, { shipments, invoices: [], lots });
  // P/L visibility rule:
  //  - Assistant & Operations: never see P/L
  //  - Sales: see P/L only for SOs they created (createdBy === their name)
  //  - Financial Director & General Manager: see all P/L
  const canSeePL = (() => {
    if (userRole === "Financial Director" || userRole === "General Manager") return true;
    if (userRole === "Sales") return !!order.createdBy && order.createdBy === userName;
    return false; // Assistant, Operations, or unknown
  })();
  const total = netTotal(order.items);
  const destination = locById(order.destinationLocationId);
  const destinationLabel = destinationDisplay(order);
  const availability = computeLineAvailability(order.items, allOrders, order.id);
  const overageCount = availability.filter(a => a.hasOverage).length;

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
      <div style={{ background: "#fff", borderBottom: "1px solid #EBEBEB", padding: "0 28px", height: 52, display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "#2563EB", fontWeight: 500 }}>← Sales Orders</button>
        <div style={{ marginLeft: "auto", display: "flex", gap: 10 }}>
          {(() => {
            const isDraft = order.status === "Draft";
            return (
              <button
                onClick={isDraft ? undefined : onPrint}
                disabled={isDraft}
                title={isDraft ? "Confirm the SO first — drafts cannot be printed or shared with clients" : ""}
                style={{
                  padding: "5px 14px", borderRadius: 7,
                  border: "1px solid #E5E7EB",
                  background: isDraft ? "#F9FAFB" : "#fff",
                  color: isDraft ? "#9CA3AF" : "#111",
                  fontSize: 12, fontWeight: 600,
                  cursor: isDraft ? "not-allowed" : "pointer"
                }}>🖨 Print / PDF</button>
            );
          })()}
          {(() => {
            const isDraft = order.status === "Draft";
            return (
              <button
                onClick={isDraft ? undefined : onEmail}
                disabled={isDraft}
                title={isDraft ? "Confirm the SO first — drafts cannot be emailed to clients" : ""}
                style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #E5E7EB", background: isDraft ? "#F9FAFB" : "#fff", color: isDraft ? "#9CA3AF" : "#111", fontSize: 12, fontWeight: 600, cursor: isDraft ? "not-allowed" : "pointer" }}
              >✉ Email Client</button>
            );
          })()}
          {(() => {
            // Issue Invoice button: only meaningful after Shipped, hidden if already invoiced.
            const shippedOrLater = ["Shipped", "Delivered", "Invoiced", "Closed"].includes(order.status);
            const alreadyInvoiced = (order.linkedInvoices && order.linkedInvoices.length > 0)
              || soInvoices.length > 0; // v6.33.0 (A3-6): register is the source of truth
            if (!shippedOrLater || alreadyInvoiced || !onIssueInvoice) return null;
            return (
              <button onClick={onIssueInvoice} style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #16A34A", background: "#16A34A", color: "#fff", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
                💰 Issue Sales Invoice
              </button>
            );
          })()}
          {order.sellIncoterm === "EXW" && !["Cancelled", "Draft"].includes(order.status) && onRecordCollection && (
            <button onClick={onRecordCollection} title="EXW: the client collects — records the pickup and creates a minimal collection shipment (no transport order, no freight on our side)."
              style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #0369A1", background: "#F0F9FF", color: "#0369A1", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>🚚 Record client collection</button>
          )}
          {["Shipped", "Delivered", "Invoiced", "Closed"].includes(order.status) && onRecordClientClaim && (
            <button onClick={onRecordClientClaim} title="The client reports a quality problem on delivered goods. Records the claim against the delivery and drafts a credit note — warehouse stock is not touched (those kg already left)."
              style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #B45309", background: "#FFFBEB", color: "#B45309", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>⚠ Record client claim</button>
          )}
          {order.status === "Cancelled"
            ? <span style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #FECACA", background: "#FEF2F2", color: "#B91C1C", fontSize: 12, fontWeight: 600 }}>Cancelled — read-only</span>
            : <button onClick={onEdit} style={{ padding: "5px 14px", borderRadius: 7, border: "1px solid #2563EB", background: "#fff", color: "#2563EB", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>✎ Edit</button>}
          <button onClick={onDelete} style={{ padding: "5px 12px", borderRadius: 7, border: "none", color: "#fff", background: "#DC2626", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Delete</button>
        </div>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: "28px 32px", background: "#FAFAFA" }}>
        <div style={{ maxWidth: 1280, margin: "0 auto" }}>
          {/* Header */}
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 20 }}>
            <div>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
                <StatusBadge status={order.status} />
              </div>
              <div style={{ fontSize: 24, fontWeight: 700, color: "#111", fontFamily: "ui-monospace, Menlo, monospace" }}>{order.number}</div>
              <div style={{ fontSize: 13, color: "#666", marginTop: 4 }}>{order.client?.name || "—"}</div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 11, color: "#888" }}>Net total</div>
              <div style={{ fontSize: 28, fontWeight: 700, color: "#111" }}>{fmtMoney(total, order.currency)}</div>
              {order.currency !== "PLN" && order.fxRate && <div style={{ fontSize: 12, color: "#888" }}>≈ {fmtMoney(total * order.fxRate, "PLN")} · rate {order.fxRate}</div>}
            </div>
          </div>

          {overageCount > 0 && (
            <div style={{ padding: "12px 16px", background: "#FFFBEB", border: "1px solid #FCD34D", borderRadius: 8, marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
              <div style={{ fontSize: 20 }}>⚠️</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#92400E" }}>
                  {overageCount} line{overageCount === 1 ? "" : "s"} exceed available supply
                </div>
                <div style={{ fontSize: 11, color: "#92400E", marginTop: 4, lineHeight: 1.5 }}>
                  This SO promises more kg than what's currently available across stock + POs (after netting other active SOs). Edit the order to reduce qty, switch source, or arrange more supply.
                </div>
              </div>
            </div>
          )}

          {/* Lifecycle bar */}
          <Card style={{ marginBottom: 16 }}>
            <SectionTitle>LIFECYCLE</SectionTitle>
            <LifecycleBar status={order.status} />
            <div style={{ marginTop: 8, fontSize: 11, color: "#888", fontStyle: "italic" }}>{SO_STATUSES[order.status]?.desc}</div>
          </Card>

          {canSeePL ? (
            <SOMarginCard order={order} lots={lots} pos={pos} shipments={shipments} operationalCosts={operationalCosts} allOrders={allOrders} />
          ) : (
            <Card style={{ marginBottom: 16 }}>
              <SectionTitle>PROFITABILITY (P/L)</SectionTitle>
              <div style={{ fontSize: 12.5, color: "#888", lineHeight: 1.5 }}>
                Profitability is hidden for your role ({userRole || "—"}). {userRole === "Sales" ? "Sales users can see P/L only for orders they created." : "P/L is visible to Sales (own orders), Financial Director, and General Manager."} You can change the active role in Settings.
              </div>
            </Card>
          )}

          <div style={{ display: "grid", gridTemplateColumns: "1.6fr 1fr", gap: 16 }}>
            <div>
              <Card style={{ marginBottom: 16 }}>
                <SectionTitle>LINE ITEMS ({order.items.length})</SectionTitle>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
                  <thead>
                    <tr style={{ background: "#F9FAFB", borderBottom: "1px solid #F3F4F6" }}>
                      <th style={{ padding: "8px 6px", textAlign: "left", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>SOURCE</th>
                      <th style={{ padding: "8px 6px", textAlign: "left", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>PRODUCT</th>
                      <th style={{ padding: "8px 6px", textAlign: "center", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>KL.</th>
                      <th style={{ padding: "8px 6px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>QTY</th>
                      <th style={{ padding: "8px 6px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>PRICE</th>
                      <th style={{ padding: "8px 6px", textAlign: "right", fontSize: 10, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>TOTAL</th>
                    </tr>
                  </thead>
                  <tbody>
                    {order.items.map((it, i) => {
                      const lt = (parseFloat(it.qty) || 0) * (parseFloat(it.unitPrice) || 0);
                      const av = availability[i] || {};
                      return (
                        <tr key={i} style={{ borderBottom: "1px solid #F9FAFB", background: av.hasOverage ? "#FFFBEB" : undefined }}>
                          <td style={{ padding: "10px 6px" }}><SourceBadge sourceType={it.sourceType} sourceRef={it.sourceRef} supplierName={it.sourceType === "PO" ? supplierNameForPO(it.sourceRef) : ""} /></td>
                          <td style={{ padding: "10px 6px" }}>
                            <div style={{ fontWeight: 600 }}>{it.product}{it.variety ? <span style={{ fontWeight: 400, color: "#666" }}> — {it.variety}</span> : null}</div>
                            <div style={{ fontSize: 11, color: "#888" }}>{it.size} · {it.origin} · {it.packaging}{it.pallets ? ` · ${it.pallets} pallets` : ""}</div>
                          </td>
                          <td style={{ padding: "10px 6px", textAlign: "center" }}><QualityBadge quality={it.quality} /></td>
                          <td style={{ padding: "10px 6px", textAlign: "right", fontWeight: 600 }}>
                            {fmtNum(it.qty)} kg
                            {av.hasOverage && (
                              <div style={{ fontSize: 10, color: "#92400E", fontWeight: 700, marginTop: 2 }}>
                                ⚠ short by {fmtNum(av.overage)} kg
                              </div>
                            )}
                            {it.sourceType && it.sourceRef && av.lineQty > 0 && !av.hasOverage && (
                              <div style={{ fontSize: 10, color: "#16A34A", fontWeight: 600, marginTop: 2 }}>
                                ✓ {fmtNum(av.combinedAvailable)} kg avail.
                              </div>
                            )}
                          </td>
                          <td style={{ padding: "10px 6px", textAlign: "right" }}>{fmtMoney(it.unitPrice, order.currency)}</td>
                          <td style={{ padding: "10px 6px", textAlign: "right", fontWeight: 700 }}>{fmtMoney(lt, order.currency)}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot>
                    <tr style={{ borderTop: "2px solid #E5E7EB" }}>
                      <td colSpan={5} style={{ padding: "10px 6px", textAlign: "right", fontSize: 11, color: "#888", fontWeight: 700, letterSpacing: "0.06em" }}>NET TOTAL</td>
                      <td style={{ padding: "10px 6px", textAlign: "right", fontWeight: 700, fontSize: 15 }}>{fmtMoney(total, order.currency)}</td>
                    </tr>
                  </tfoot>
                </table>
              </Card>

              {order.notes && (
                <Card style={{ marginBottom: 16 }}>
                  <SectionTitle>NOTES</SectionTitle>
                  <div style={{ fontSize: 12.5, color: "#444", lineHeight: 1.5, whiteSpace: "pre-wrap" }}>{order.notes}</div>
                </Card>
              )}
            </div>

            <div>
              <Card style={{ marginBottom: 16 }}>
                <SectionTitle>CLIENT</SectionTitle>
                <div style={{ fontSize: 13, fontWeight: 700 }}>{order.client?.name || "—"}</div>
                <div style={{ fontSize: 11, color: "#888", marginTop: 3 }}>NIP {order.client?.nip || "—"}</div>
                <div style={{ fontSize: 11, color: "#666", marginTop: 4 }}>{order.client?.address || "—"}</div>
                <div style={{ fontSize: 11, color: "#666", marginTop: 4 }}>{order.client?.contact || "—"}</div>
              </Card>

              <Card style={{ marginBottom: 16 }}>
                <SectionTitle>TERMS</SectionTitle>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <div><div style={{ fontSize: 10, color: "#888" }}>ORDER DATE</div><div style={{ fontWeight: 500 }}>{fmtDate(order.orderDate)}</div></div>
                  <div><div style={{ fontSize: 10, color: "#888" }}>DELIVERY DATE</div><div style={{ fontWeight: 500 }}>{fmtDate(order.deliveryDate)}</div></div>
                  <div><div style={{ fontSize: 10, color: "#888" }}>SELL INCOTERM</div><div style={{ fontWeight: 600 }}>{order.sellIncoterm || "—"}</div></div>
                  <div><div style={{ fontSize: 10, color: "#888" }}>CURRENCY</div><div style={{ fontWeight: 600 }}>{order.currency} {order.fxLockedAt ? "🔒" : ""}</div></div>
                  <div style={{ gridColumn: "span 2" }}><div style={{ fontSize: 10, color: "#888" }}>PAYMENT TERMS</div><div style={{ fontWeight: 500 }}>{order.paymentTerms === "Other" ? order.paymentTermsOther : order.paymentTerms}</div></div>
                  <div style={{ gridColumn: "span 2" }}><div style={{ fontSize: 10, color: "#888" }}>DESTINATION</div><div style={{ fontWeight: 500 }}>{destinationLabel !== "—" ? `${destination ? LOCATION_TYPES[destination.type]?.icon : "📍"} ${destinationLabel}` : "—"}</div></div>
                  {order.importPermitNo && <div><div style={{ fontSize: 10, color: "#888" }}>IMPORT PERMIT NO.</div><div style={{ fontWeight: 600, fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12.5 }}>{order.importPermitNo}</div></div>}
                  {order.acidNo && <div><div style={{ fontSize: 10, color: "#888" }}>ACID NO.</div><div style={{ fontWeight: 600, fontFamily: "ui-monospace, Menlo, monospace", fontSize: 12.5 }}>{order.acidNo}</div></div>}
                </div>
              </Card>

              {soInvoices.length > 0 && (
                <Card style={{ marginBottom: 16, border: "1px solid #BBF7D0", background: "#F0FDF4" }}>
                  <SectionTitle>SALES INVOICE READY</SectionTitle>
                  {soInvoices.map((inv, idx) => (
                    <div key={idx} style={{ background: "#fff", border: "1px solid #BBF7D0", borderRadius: 8, padding: "10px 12px", marginBottom: 6 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
                        <div>
                          <div style={{ fontSize: 13, fontWeight: 700, color: "#16A34A", fontFamily: "ui-monospace, Menlo, monospace" }}>{inv.number}</div>
                          <div style={{ fontSize: 10, color: "#888", marginTop: 1 }}>SINV · Issue {formatDMY(inv.issueDate)} · Due {formatDMY(inv.dueDate)}</div>
                        </div>
                        <div style={{ padding: "2px 8px", background: "#DCFCE7", color: "#16A34A", borderRadius: 4, fontSize: 9.5, fontWeight: 700, letterSpacing: "0.04em" }}>READY</div>
                      </div>
                      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 6, fontSize: 11, color: "#444" }}>
                        <div>Net: <strong>{fmtMoney(inv.netAmount, inv.currency)}</strong></div>
                        <div>VAT ({inv.vatRate}%): <strong>{fmtMoney(inv.vatAmount, inv.currency)}</strong></div>
                        <div style={{ gridColumn: "span 2", paddingTop: 4, borderTop: "1px solid #F3F4F6" }}>Gross: <strong style={{ fontSize: 13, color: "#111" }}>{fmtMoney(inv.grossAmount, inv.currency)}</strong></div>
                      </div>
                    </div>
                  ))}
                  {soInvoices.some(inv => inv.fakturownia?.exported) ? (
                    <div style={{ fontSize: 10.5, color: "#0C4A6E", marginTop: 8, lineHeight: 1.5, padding: "7px 10px", background: "#F0F9FF", border: "1px solid #BAE6FD", borderRadius: 6 }}>
                      {soInvoices.filter(inv => inv.fakturownia?.exported).map((inv, i) => (
                        <div key={i}>✓ Matched in Fakturownia{inv.fakturownia?.ksef ? <> · KSeF <span style={{ fontFamily: "ui-monospace, Menlo, monospace" }}>{inv.fakturownia.ksef}</span></> : null} · <strong>{inv.fakturownia?.paid ? "PAID" : "unpaid"}</strong></div>
                      ))}
                    </div>
                  ) : (
                    <div style={{ fontSize: 10, color: "#16A34A", marginTop: 8, lineHeight: 1.4, fontStyle: "italic" }}>
                      Enter this invoice in Fakturownia, then use "Match from Fakturownia" to pull its KSeF number and paid status.
                    </div>
                  )}
                  {fktConfigured && (
                    <button onClick={() => onMatchInvoices(order)} disabled={fktMatching} style={{ marginTop: 8, padding: "6px 12px", borderRadius: 7, border: "none", background: fktMatching ? "#A7F3D0" : "#16A34A", color: "#fff", fontSize: 11.5, fontWeight: 700, cursor: fktMatching ? "wait" : "pointer", fontFamily: "inherit" }}>{fktMatching ? "Matching…" : "↻ Match from Fakturownia (read-only)"}</button>
                  )}
                  {fktMatchMsg && <div style={{ fontSize: 10.5, color: fktMatchMsg.kind === "error" ? "#DC2626" : "#15803D", marginTop: 6 }}>{fktMatchMsg.text}</div>}
                </Card>
              )}

              {(computedLinks.linkedInvoices?.length > 0 || computedLinks.linkedShipments?.length > 0) && (
                <Card style={{ marginBottom: 16 }}>
                  <SectionTitle>LINKED RECORDS</SectionTitle>
                  {computedLinks.linkedInvoices?.length > 0 && (
                    <div style={{ marginBottom: 8 }}>
                      <div style={{ fontSize: 10, color: "#888", marginBottom: 4 }}>SALES INVOICES</div>
                      {computedLinks.linkedInvoices.map(inv => (
                        <div key={inv} style={{ display: "inline-block", padding: "4px 8px", margin: "2px", background: "#EFF6FF", border: "1px solid #BFDBFE", borderRadius: 5, fontSize: 11, fontWeight: 600, color: "#1D4ED8", fontFamily: "ui-monospace, Menlo, monospace" }}>{inv}</div>
                      ))}
                    </div>
                  )}
                  {computedLinks.linkedShipments?.length > 0 && (
                    <div>
                      <div style={{ fontSize: 10, color: "#888", marginBottom: 4 }}>SHIPMENTS</div>
                      {computedLinks.linkedShipments.map(s => (
                        <div key={s} style={{ display: "inline-block", padding: "4px 8px", margin: "2px", background: "#F3E8FF", border: "1px solid #DDD6FE", borderRadius: 5, fontSize: 11, fontWeight: 600, color: "#7C3AED", fontFamily: "ui-monospace, Menlo, monospace" }}>{s}</div>
                      ))}
                    </div>
                  )}
                </Card>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

